INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6653', 'spa', 'manojos, gavillas; haces de espigas de grano atados y dejados para el espigueo', 'Este sustantivo plural designa manojos o gavillas de grano, es decir, tallos atados en el campo durante la siega. En Rut 2, Booz ordena a sus trabajadores que saquen deliberadamente espigas de estos manojos y las dejen para que Rut las recoja. La palabra se integra así en los temas centrales del relato: la provisión y la bondad. Lo que parece casual es en realidad generosidad intencionada. Los manojos representan la abundancia de la cosecha y las estructuras sociales que permiten sobrevivir a los más vulnerables.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6654', 'spa', 'Lado, flanco; referido a partes del cuerpo, caras de estructuras y como preposición: ''al lado de'' o ''junto a''', 'Lado, flanco; referido a partes del cuerpo, caras de estructuras y como preposición: ''al lado de'' o ''junto a''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6656', 'spa', '¿es verdad? (interrogativo en arameo); cuestionar la veracidad de un informe', 'Esta expresión interrogativa en arameo pregunta si algo es cierto o real. En Daniel 3:14, Nabucodonosor la emplea para interpelar a los tres jóvenes hebreos: «¿Es verdad que no servís a mis dioses?». La frase expresa duda o exige confirmación, con un matiz amenazante. Las variantes textuales sugieren incertidumbre de los copistas sobre la forma exacta, pero la fuerza interrogativa es clara: el rey demanda una respuesta que determinará el destino de aquellos hombres.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6658b', 'spa', 'ser asolado, devastado; quedar desolado (Nifal pasivo)', 'Este verbo en su forma pasiva significa ser asolado o devastado, y describe la destrucción de ciudades. En Sofonías 3:6, Dios declara que ha exterminado naciones y sus ciudades han quedado devastadas: ruinas vacías sin habitantes. La raíz transmite destrucción total, la anulación de la vida urbana y la seguridad. Es lenguaje profético de juicio, donde ciudades prósperas se convierten en pueblos fantasma, monumentos a la ira divina contra la injusticia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6659', 'spa', 'Nombre propio hebreo que significa ''justo'' o ''recto,'' derivado de la raíz צ-ד-ק. El Sadoc más prominente es el sacerdote que sirvió fielmente bajo Dav', 'Nombre propio hebreo que significa ''justo'' o ''recto,'' derivado de la raíz צ-ד-ק. El Sadoc más prominente es el sacerdote que sirvió fielmente bajo David durante la rebelión de Absalón (2 S 15:24-29) y ungió a Salomón como rey (1 R 1:39). Sus descendientes, los ''hijos de Sadoc,'' se convirtieron en la línea sacerdotal legítima en la visión del templo de Ezequiel (Ez 40:46; 44:15; 48:11). El nombre también pertenece al suegro de Uzías (2 R 15:33), dos constructores del muro en la época de Nehemías (Neh 3:4, 29) y varias figuras en las genealogías del Cronista. Su transliteración uniforme en distintas lenguas (griego Σαδώκ, español Sadoc) refleja su condición de nombre propio fijo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6661', 'spa', 'Sidim (o Tsidim), ciudad fortificada en el territorio de Neftalí', 'Sidim figura entre las ciudades fortificadas asignadas a la tribu de Neftalí en el libro de Josué. El nombre podría derivar de una raíz que significa «lado» o «fortificación», aunque su etimología exacta es incierta. La versión de los Setenta muestra variación textual. Como ocurre con muchos topónimos en las listas de conquista, disponemos de poca información más allá de su inclusión en los límites tribales, pero tales listas eran fundamentales para establecer reclamos territoriales y preservar la memoria geográfica de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6662', 'spa', 'Justo, recto; de personas que obran rectamente, de la perfección moral de Dios, de naciones, o de tener la razón en sentido forense', 'Uno de los términos morales fundamentales del Antiguo Testamento: tsaddiq describe la conformidad con una norma de rectitud, ya sea ética, pactual o jurídica. Noé es la primera persona llamada tsaddiq (Gn 6:9), y la intercesión de Abraham por Sodoma gira en torno a la distinción entre el justo y el impío (Gn 18:23-25). Cuando se predica de Dios, el vocablo adquiere una resonancia más profunda: YHWH es justo en todos sus caminos (Sal 145:17), fiel en el juicio (Sal 119:137) y recto aun cuando su pueblo sufre (Lm 1:18). Las formas honoríficas coreanas como ''의로우시다'' y el alemán ''der Gerechte'' reservan un registro especial para este uso divino, sugiriendo cuán universalmente los traductores perciben la fuerza elevada del término aplicado a Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6663', 'spa', 'Ser justo o tener razón; declarar justo, justificar, absolver o vindicar; el verbo central de la justicia y la rectitud bíblicas', 'Ser justo o tener razón; declarar justo, justificar, absolver o vindicar; el verbo central de la justicia y la rectitud bíblicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6664', 'spa', 'Justicia, rectitud; la norma moral de lo recto, equitativo y correcto ante Dios y en la sociedad', 'Uno de los términos éticos fundamentales de la Biblia hebrea: tsedheq nombra la norma por la cual las pesas son honestas (Lv 19:36), los jueces gobiernan con equidad (Dt 1:16) y Dios actúa fielmente (Sal 4:2; Is 45:19). El alemán Gerechtigkeit y el francés justice capturan el amplio alcance moral y jurídico. El vocablo rige tanto la equidad comercial concreta (''pesas y medidas justas'', Lv 19:36; Dt 25:15) como la descripción del rey mesiánico que reinará con justicia (Is 32:1). En algunos pasajes funciona predicativamente como adjetivo —''juicio justo'' (Dt 16:18), ''pesa justa y cabal'' (Dt 25:15)— donde el español justa y el alemán gerecht confirman el desplazamiento adjetival.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6665', 'spa', 'justicia, rectitud (arameo); integridad moral y actuación justa', 'Este término arameo corresponde al hebreo צְדָקָה y significa justicia o acción recta. En Daniel 4, aparece en el consejo del profeta a Nabucodonosor: abandona tus pecados practicando la justicia y muestra misericordia a los oprimidos. El vocablo es tanto jurídico como ético: hacer lo correcto ante los ojos de Dios, especialmente en el trato hacia los vulnerables. La palabra une moralidad personal y justicia social, insistiendo en que la relación correcta con Dios debe manifestarse en el trato justo hacia los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6666', 'spa', 'Justicia, rectitud; conducta recta ante Dios y la sociedad; actos concretos de justicia o de vindicación', 'Uno de los conceptos morales culminantes de la Biblia hebrea: tsedaqah denota la conformidad con una norma de rectitud, ya sea el carácter mismo de Dios, la relación pactual o las exigencias de la justicia social. Cuando Abram creyó la promesa de Dios, ''le fue contado por tsedaqah'' (Gn 15:6), estableciendo el peso teológico del término por milenios. Los reyes se miden por si ejecutan ''juicio y tsedaqah'' (2 S 8:15; Jer 22:3), y los profetas claman contra quienes la convierten en ajenjo (Am 5:7; 6:12). En plural, tsidqot pasa de la cualidad abstracta a los actos concretos: las ''justicias del Señor'' recitadas en asambleas tribales (Jue 5:11; 1 S 12:7) o los ''trapos de inmundicia'' de los esfuerzos humanos (Is 64:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6667', 'spa', 'צִדְקִיָּהוּ (Sedequías) es un nombre propio teofórico que significa ''Yahvé es mi justicia,'' portado por varias figuras en la Biblia hebrea. El más de', 'צִדְקִיָּהוּ (Sedequías) es un nombre propio teofórico que significa ''Yahvé es mi justicia,'' portado por varias figuras en la Biblia hebrea. El más destacado es el último rey de Judá, originalmente llamado Matanías, a quien Nabucodonosor renombró e instaló como rey vasallo (2 R 24:17). Su desdichado reinado de once años terminó con la caída de Jerusalén, la destrucción del Templo y su cegamiento tras presenciar la ejecución de sus hijos (2 R 25:1-7; Jer 39:1-7). El nombre también pertenece a un falso profeta bajo Acab (1 R 22:11, 24) y a un falso profeta en tiempos de Jeremías (Jer 29:21-22). Con 63 apariciones, el nombre se concentra sobre todo en Jeremías.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6668', 'spa', 'pulido, reluciente; bronce u otro metal bruñido hasta alcanzar un brillo intenso', 'Este participio describe metal que ha sido pulido hasta resplandecer. En Esdras 8:27, se refiere a vasijas de bronce que relucen o brillan, objetos preciosos transportados de regreso a Jerusalén. El verbo sugiere bruñir hasta lograr un lustre elevado, haciendo que el metal refleje la luz de manera brillante. Es una palabra de artesanía y valor: no se trata de bronce común, sino de metal refinado y acabado con esmero, digno del servicio del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6669', 'spa', 'amarillo, resplandeciente; describe el color amarillento del cabello en diagnósticos de pureza/enfermedad de la piel', 'Este adjetivo describe una cualidad amarillenta o resplandeciente, apareciendo exclusivamente en Levítico 13 dentro de los diagnósticos sacerdotales para enfermedades de la piel. La palabra caracteriza el color del cabello que ayuda a los sacerdotes a determinar la impureza ritual: cabello amarillo en un área infectada señala inmundicia, mientras que cabello negro normal sugiere sanidad. La naturaleza técnica es evidente en las traducciones consistentes entre idiomas: ''yellow'' (inglés), ''amarillo'' (español), ''jaune'' (francés), ''gelb'' (alemán). Esta terminología de color era crucial para el diagnóstico levítico, distinguiendo tejido sano de tejido enfermo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6670', 'spa', 'relinchar (como un caballo); expresar excitación lujuriosa o júbilo desenfrenado', 'Este verbo describe el relincho o el grito de los caballos, usado metafóricamente para la conducta humana. En Jeremías 50:11, se aplica a los guerreros de Babilonia, sugiriendo una exultación lujuriosa o triunfante. La imagen es animalesca, reduciendo a los conquistadores a bestias en celo o sementales pavoneándose en victoria. La literatura profética emplea con frecuencia imágenes animales para criticar los excesos humanos, y aquí el relincho capta tanto la arrogancia como el apetito desenfrenado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6670a', 'spa', 'Gritar agudamente, clamar de gozo; relinchar (de caballos, metafórico para la lujuria).', 'El verbo צָהַל capta dos sonidos notablemente distintos unidos por su cualidad aguda y penetrante. En su uso principal, es un grito de exultación y alabanza: «¡Grita de gozo, oh habitante de Sion!» (Is 12:6), frecuentemente en paralelo con ranan («cantar de alegría»). En Ester 8:15, la ciudad de Susa «clamó» de alegría por la honra de Mardoqueo. Pero Jeremías reutiliza la palabra para el relincho de los caballos, aplicado metafóricamente a hombres consumidos por la lujuria (Jer 5:8) y a caldeos arrogantes que «relinchan» en triunfo (Jer 50:11). El cognado árabe ṣahala («relinchar») confirma la conexión equina como la imagen acústica originaria del término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6670b', 'spa', 'hacer brillar, hacer resplandecer; dar luminosidad al rostro', 'Este verbo en forma Hiphil significa hacer que algo brille o resplandezca, y se usa en el Salmo 104 para describir cómo el rostro se vuelve radiante. Dios da aceite para hacer brillar el rostro, señal de salud, gozo y bienestar. Un rostro resplandeciente indica prosperidad y favor divino, mientras que un rostro ensombrecido sugiere dolor o vergüenza. El verbo capta la evidencia visible del florecimiento interior, el resplandor físico que acompaña una vida vivida bajo la bendición de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6671', 'spa', 'prensar aceite, extraer aceite de aceitunas; el trabajo de la producción de aceite', 'Este verbo denominativo significa prensar o extraer aceite, específicamente de aceitunas. En Job 24:11, aparece en un lamento sobre la injusticia: los trabajadores prensan aceite dentro de los muros de los malvados, pero ellos mismos pasan sed. El verbo capta el arduo trabajo agrícola de triturar aceitunas para liberar su aceite, una labor valiosa que debería traer recompensa pero que aquí solo trae explotación. Es una instantánea de la opresión económica: los obreros enriquecen a otros mientras permanecen en la pobreza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6672a', 'spa', 'Mediodía — el momento culminante del día cuando el sol está en su punto más alto, marcando un tiempo específico o brillo metafórico', 'Mediodía — el momento culminante del día cuando el sol está en su punto más alto, marcando un tiempo específico o brillo metafórico');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6672b', 'spa', 'techo, cubierta; la parte superior del arca, posiblemente un tragaluz o estructura de techo', 'Este sustantivo femenino probablemente se refiere a un techo o algún tipo de abertura o cubierta en la parte superior. En Génesis 6:16, Dios instruye a Noé que haga un צֹהַר para el arca, terminándolo a un codo hacia arriba. Las interpretaciones varían: algunos lo ven como un techo, otros como una ventana o tragaluz para luz y ventilación. Las versiones antiguas discrepaban y los eruditos modernos siguen sin certeza. Lo que queda claro es que se trata de un elemento arquitectónico en la parte superior del arca, esencial para completar la estructura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6673', 'spa', 'Precepto, mandato, regla; usado en la frase repetitiva de Isaías ''mandato sobre mandato'' y en Oseas 5:11.', 'Sustantivo poco frecuente que aparece casi exclusivamente en Isaías 28:10, 13, donde forma parte del estribillo burlón tsav la-tsav, tsav la-tsav (''mandato sobre mandato''). Los eruditos debaten si esto representa contenido genuino —un pueblo hastiado que imita la instrucción moral repetitiva de Isaías— o sílabas sin sentido que remedan a un maestro monótono. Oseas 5:11 emplea la forma relacionada para designar un ''mandato'' que Efraín siguió obstinadamente. El español ''mandato'' y el alemán ''Gebot'' lo traducen como una directiva o mandamiento, preservando el tono autoritativo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6674', 'spa', 'inmundo, manchado de excremento; describe vestiduras o condiciones de severa contaminación y degradación', 'La palabra denota algo inmundo o contaminado, con conexión al excremento. En 2 Reyes 18:27, se describen las terribles condiciones del asedio donde la gente comerá sus propios desechos. En Zacarías 3:3-4, el sumo sacerdote Josué está de pie ante el ángel vistiendo ''vestiduras inmundas'', simbolizando el pecado de la nación que será removido y reemplazado con ropas limpias. El español (''sucias''—sucias/inmundas) y el francés (''souillé''—manchado) capturan el sentido de contaminación. Esto no es mera suciedad sino profunda contaminación, ya sea literal o simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6675', 'spa', 'Inmundicia, excremento; metafóricamente, impureza moral o espiritual', 'Esta palabra denota suciedad literal o excremento, pero se extiende metafóricamente a la corrupción moral. Proverbios 30:12 describe una generación que no ha sido limpiada ''de su inmundicia''. Isaías 4:4 habla de lavar la ''inmundicia'' de las hijas de Jerusalén. Isaías 28:8 describe vívidamente mesas cubiertas con la ''suciedad'' del vómito. 2 Reyes 18:27 (paralelo en Isaías 36:12) emplea la lectura Qeré para referirse al excremento humano en el contexto de un asedio. La palabra conlleva fuertes connotaciones de contaminación, ya sea desecho corporal literal o corrupción moral figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6676', 'spa', 'cuello (voz aramea, cognado del hebreo צַוָּאר)', 'Palabra aramea para el cuello humano, que aparece exclusivamente en Daniel. En Daniel 5 se usa tres veces en referencia a la colocación de una cadena de oro alrededor del cuello como signo de alto cargo y honor. Oseas 10:11 emplea el cognado hebreo para describir el cuello de Efraín sometido al yugo. El cuello simboliza tanto la dignidad cuando es adornado con oro como la sumisión cuando se le impone un yugo. En el contexto de Daniel, recibir la cadena representa la promoción al tercer puesto más alto del reino de Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6677a', 'spa', 'Cuello, nuca — la parte del cuerpo que une cabeza y torso; lugar de abrazo, adorno y sometimiento', 'Cuello, nuca — la parte del cuerpo que une cabeza y torso; lugar de abrazo, adorno y sometimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6677b', 'spa', 'collares, adornos que se llevan alrededor del cuello; joyas que evocan belleza y ornamento', 'Este sustantivo plural designa los collares o cadenas ornamentales que se llevaban alrededor del cuello. En Cantares 4:9, se alaba la belleza de la amada: una sola mirada de sus ojos, una sola joya de su collar, ha cautivado el corazón del amante. Es una imagen de adorno y encanto, donde la joya realza y a la vez simboliza la presencia cautivadora de la mujer. En la cultura del antiguo Cercano Oriente, los collares eran indicadores de riqueza, posición social y feminidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6678', 'spa', 'Soba — ciudad-estado aramea en la región del valle de la Becá, cuyo rey Hadad-ezer fue derrotado por David.', 'Soba (צוֹבָה) identifica una poderosa ciudad-estado aramea situada en la región del valle de la Becá, entre Hamat y Damasco. Aparece de manera prominente en las guerras de David, donde Hadad-ezer, rey de Soba, es derrotado junto al Éufrates (2 S 8:3-5, 12; 1 Cr 18:3-9). Los amonitas contrataron a los arameos de Soba contra David (2 S 10:6, 8), y también Saúl combatió contra los reyes de Soba (1 S 14:47). Tras las conquistas de David, Rezón huyó de Soba para establecer un reino rival en Damasco (1 R 11:23-24). Salomón sometió Hamat-Soba (2 Cr 8:3). El compuesto «Aram-Soba» aclara la identidad aramea del territorio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6679a', 'spa', 'Cazar animales de caza; perseguir o acechar figuradamente a una persona; atrapar o enredar almas (Piel intensivo)', 'Cazar animales de caza; perseguir o acechar figuradamente a una persona; atrapar o enredar almas (Piel intensivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6679b', 'spa', 'aprovisionarse, tomar provisiones; reunir víveres para un viaje', 'Este verbo en forma hitpael significa abastecerse de provisiones o tomar alimentos para un viaje. En Josué 9, los gabaonitas afirman haber tomado pan como provisión desde sus casas, aunque ya estaba mohoso, como parte de su engaño. El verbo implica una preparación deliberada: empacar suministros para el camino. Es el acto de aprovisionamiento que cualquier viajero o expedición militar emprendería, reuniendo víveres para sustentarse durante la travesía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6680', 'spa', 'Mandar, ordenar, encargar; en Pual, ser mandado; por extensión, designar, comisionar o enviar un mensaje', 'En Piel, tsavah es el verbo de referencia de la Biblia hebrea para el habla con autoridad: el vocablo empleado cuando Dios ordena a Noé construir el arca (Gn 6:22), cuando Moisés transmite los mandamientos de la Torá a Israel y cuando los reyes emiten decretos reales. Su enorme frecuencia (496 ocurrencias) refleja la centralidad de la dinámica mandato-obediencia en la cosmovisión bíblica. El cognado árabe wasiya (''encargar, encomendar'') conserva el mismo núcleo semántico, mientras que el cognado siríaco tswa se desplaza hacia lo físico —''apilar piedras''—, insinuando un trasfondo concreto antiguo de erigir mojones como directivas fijas. El Pual pasivo (''ser mandado'') aparece escasamente pero con peso, y algunos usos notables se extienden más allá del simple ordenar hacia el nombramiento de líderes y el envío de mensajes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6681', 'spa', 'clamar en voz alta, gritar; expresión vocal intensa de gozo o angustia', 'Este verbo significa clamar o gritar con fuerza, y se usa tanto para vocalizaciones de alegría como de aflicción. En Isaías 42:11, aparece en una invitación para que el desierto y sus ciudades alcen la voz con júbilo, en paralelo con el canto. El contexto determina si se trata de un grito de triunfo, de celebración o de angustia. Cognados en árabe y arameo confirman el sentido de expresión vocal fuerte, el tipo de clamor que exige atención o que brota de una emoción desbordante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6682', 'spa', 'clamor, grito de angustia o aflicción', 'Sustantivo femenino que denota un grito fuerte, generalmente en contextos de angustia, duelo o calamidad. Salmo 144:14 lo emplea en sentido negativo: «que no haya clamor en nuestras calles» como señal de paz. Isaías 24:11 describe un clamor en las calles por la falta de vino en medio del juicio divino. Jeremías lo usa dos veces: para el lamento de Judá durante la sequía (14:2) y para el grito que llenará la tierra cuando Egipto sea derrotado (46:12). La palabra transmite la expresión vocal de dolor profundo o alarma pública.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6683', 'spa', 'el abismo, las profundidades oceánicas; las aguas primordiales o abismales', 'Este sustantivo designa las aguas profundas, el abismo oceánico, a menudo con connotaciones cosmogónicas. En Isaías 44:27, Dios se dirige al abismo ordenándole que se seque, demostrando su dominio soberano sobre las aguas caóticas. La palabra evoca tanto la liberación del Mar Rojo como las imágenes de la creación, donde la palabra de Dios somete los mares indómitos. Es símbolo de peligro, caos y lo desconocido, pero siempre sujeto al mandato divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6684', 'spa', 'Ayunar, abstenerse voluntariamente de alimento como acto de duelo, penitencia o devoción ante Dios', 'Ayunar, abstenerse voluntariamente de alimento como acto de duelo, penitencia o devoción ante Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6685', 'spa', 'Ayuno — abstención voluntaria de alimento como acto de duelo, arrepentimiento, petición o consagración ante Dios', 'Ayuno — abstención voluntaria de alimento como acto de duelo, arrepentimiento, petición o consagración ante Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6686', 'spa', 'Zuar; padre de Natanael, líder tribal de Isacar', 'Zuar es un isacarita cuyo nombre significa ''pequeño'' o ''insignificante''. Se le conoce exclusivamente como el padre de Natanael, el líder que representó a la tribu de Isacar durante el censo del desierto, la disposición del campamento y las ofrendas de dedicación del tabernáculo. Las cinco apariciones siguen la fórmula patronímica fija ''Natanael hijo de Zuar'' (Nm 1:8; 2:5; 7:18, 23; 10:15), insertando el nombre firmemente dentro del marco organizativo de la estructura tribal del Israel primitivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6687', 'spa', 'fluir, desbordar, flotar; agua en movimiento que cubre algo o hace que algo se eleve en la superficie', 'Este verbo captura el agua en movimiento: fluyendo sobre algo, desbordando límites, o haciendo que objetos floten. Deuteronomio 11:4 describe cómo Dios hizo que las aguas del Mar Rojo fluyeran sobre el ejército de Faraón. En 2 Reyes 6:6, Eliseo hace flotar una cabeza de hacha de hierro sobre el agua—una inversión milagrosa. Lamentaciones 3:54 lo usa figuradamente: ''las aguas fluyeron sobre mi cabeza'', expresando estar abrumado por la calamidad. Las traducciones francesa y alemana preservan matices causativos (''hizo desbordar'', ''flotó''), reflejando tanto el movimiento natural del agua como la intervención sobrenatural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6689', 'spa', 'Zuf; antepasado efraimita de Samuel; también un distrito en Benjamín', 'Zuf designa tanto a una persona como a un lugar. Como persona, fue un antepasado efraimita (o levita) de Elcana y, por tanto, del profeta Samuel (1 S 1:1; 1 Cr 6:26, 35). La tierra de Zuf era un distrito en el territorio de Benjamín donde Saúl y su criado buscaban las burras perdidas antes de encontrarse con Samuel (1 S 9:5). El nombre podría estar relacionado con la raíz que significa ''panal de miel'', aunque su etimología sigue siendo incierta. La variante Zofay (1 Cr 6:26) probablemente se refiere al mismo individuo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6691', 'spa', 'Zofar (nombre propio, tercer amigo de Job, oriundo de Naamat)', 'Uno de los tres amigos de Job que vinieron a consolarlo, pero terminaron argumentando que su sufrimiento debía ser consecuencia del pecado. Zofar es identificado como «el naamatita» y aparece en los diálogos de Job con dos discursos principales (capítulos 11 y 20) y en la reconciliación final (42:9). Su nombre posiblemente derive de una raíz que significa «pájaro» o «gorjear», aunque esto es incierto. Zofar representa una teología rígida de la retribución: los malvados siempre sufren, de modo que el sufrimiento de Job implicaría culpa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6692a', 'spa', 'Florecer, brotar, reverdecer; hacer germinar, producir flores (causativo).', 'El verbo צוּץ evoca el instante en que una planta estalla en flor: la aparición súbita y visible de la vida. En el Qal, describe la hierba que «florece» por la mañana (Sal 90:6), los justos que «florecen» como la vegetación (Sal 92:7) y la belleza efímera de la vida humana comparada con la flor del campo (Sal 103:15). La corona sobre el heredero de David «resplandecerá» o «florecerá» (Sal 132:18), extendiendo la imagen a la gloria real. En el Hifil causativo, designa el milagroso retoñar de la vara de Aarón (Nm 17:8) y el futuro florecimiento de Israel (Is 27:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6692b', 'spa', 'mirar fijamente, atisbar, observar con atención; espiar a través de una abertura', 'Este verbo en forma hifil significa mirar fijamente o atisbar con intensidad, especialmente a través de una abertura estrecha. En Cantares 2:9, se describe al amado asomándose por la celosía o mirando a través de las ventanas, una imagen de observación anhelante y llena de deseo. El verbo sugiere una mirada concentrada e intensa, alguien que intenta ver a través de una barrera. Es una palabra de deseo y anticipación: los ojos del amante buscando un atisbo de la persona amada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6693', 'spa', 'Oprimir, constreñir, poner en aprietos; de presión de asedio, insistencia persistente y opresión', 'Verbo en Hifil que significa oprimir, constreñir o poner en aprietos, abarcando el asedio militar, la urgencia personal y la opresión sistemática. En Deuteronomio 28:53-57 describe los terribles aprietos de un asedio — el enemigo presionando con tal fuerza que la gente recurre a lo impensable. El árabe emplea formas de dayaaqa (''estrechar, constreñir''), revelando la metáfora raíz de reducir el espacio. Dalila ''presionó'' a Sansón con insistencia implacable (Jue 16:16), mientras que el coreano ''joruda'' (acosar) capta el matiz interpersonal. Isaías usa el participio sustantivado para designar al ''opresor'' — aquel que hace la vida insoportablemente estrecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6694', 'spa', 'derramar, fundir; líquido siendo derramado o metal siendo fundido del mineral', 'El verbo describe derramar líquido o fundir material sólido. Job 28:2 habla de fundir cobre de la piedra—derritiendo mineral en metal. Job 29:6 recuerda la prosperidad cuando ''la roca derramaba corrientes de aceite junto a mí'', una metáfora de bendición abundante. Isaías 26:16 es textualmente incierto pero probablemente involucra derramar oraciones susurradas bajo angustia. Las traducciones españolas distinguen ''derramaba'' (derramó) de ''funde'' (derrite/funde), reconociendo tanto el contexto metalúrgico como el líquido. La imaginería se mueve del proceso industrial a la abundancia poética a la petición desesperada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6695a', 'spa', 'angustia, estrechez; presión y dificultad de los tiempos', 'Este sustantivo se refiere a la angustia, la estrechez o la presión: circunstancias difíciles que oprimen y constriñen por todos lados. En Daniel 9:25 aparece en la enigmática frase «en tiempos de angustia», describiendo el período durante el cual Jerusalén y el templo serán reconstruidos. La palabra captura la adversidad y la oposición que marcarán la restauración, un tiempo de edificación bajo presión constante. No se trata de simple dificultad, sino de constricción, como estar apremiado desde todos los flancos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6695b', 'spa', 'angustia, congoja, presión; aflicción severa y restricción, a menudo emparejada con tribulación (tsarah)', 'Este sustantivo denota angustia o congoja intensa, típicamente apareciendo junto a su casi-sinónimo צָרָה (tribulación). Proverbios 1:27 advierte que la calamidad vendrá ''como tribulación y angustia'' a quienes rechazan la sabiduría. Isaías 8:22 y 30:6 describen crisis nacionales como ''angustia y congoja''—la experiencia de estar bajo presión extrema sin escape. El español ''congoja'' (angustia) y ''aflicción'' (aflicción) capturan el peso emocional, mientras que el emparejamiento con ''tribulación'' a lo largo enfatiza sufrimiento compuesto. Esta es angustia que restringe y aplasta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6696a', 'spa', 'Sitiar, poner sitio a una ciudad; atar o amarrar con firmeza; oprimir, angustiar; cercar o encerrar', 'Sitiar, poner sitio a una ciudad; atar o amarrar con firmeza; oprimir, angustiar; cercar o encerrar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6696b', 'spa', 'mostrar hostilidad, tratar como enemigo, hostigar u oprimir', 'Verbo que significa actuar con hostilidad hacia alguien, tratarlo como adversario o enemigo. Éxodo 23:22 promete protección divina: «seré enemigo de tus enemigos», en paralelo con «me opondré a quienes se te opongan». Deuteronomio lo usa dos veces prohibiendo a Israel hostigar a Moab (2:9) y a Amón (2:19), pues esas tierras fueron asignadas por Dios a los descendientes de Lot. Ester 8:11 permite a los judíos destruir a «quienes los ataquen». La palabra enfatiza hostilidad activa y comportamiento opresivo, no simple antipatía.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6696c', 'spa', 'formar, moldear, dar forma; crear o delinear un objeto deliberadamente', 'Este verbo significa formar, moldear o delinear: dar forma a algo de manera deliberada, ya sea físicamente o mediante un diseño. En 1 Reyes 7:15, en una lectura enmendada, podría describir la fabricación de las columnas de bronce del templo, aunque las dificultades textuales complican la interpretación. La raíz está vinculada al trabajo artesanal, la transformación intencional de materia prima en un producto terminado. Se superpone con el verbo más común para formar o crear, pero enfatiza el diseño intencional del artesano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6697', 'spa', 'El sustantivo hebreo צוּר se ancla en la solidez de la piedra: un peñasco, un risco escarpado, un lugar donde uno se esconde del enemigo o donde Dios ', 'El sustantivo hebreo צוּר se ancla en la solidez de la piedra: un peñasco, un risco escarpado, un lugar donde uno se esconde del enemigo o donde Dios hace brotar agua milagrosamente. Moisés golpeó el צוּר en Horeb (Éx 17:6) y en Meriba; la roca produjo miel y aceite en el Cántico de Moisés (Dt 32:13). Pero quizá el uso más teológicamente resonante es como epíteto divino: ''La Roca, su obra es perfecta'' (Dt 32:4). El español distingue con nitidez entre ''roca'' para la formación geológica y ''Roca'' con mayúscula para la deidad. Dos sentidos especializados completan la palabra: cuchillos de pedernal para la circuncisión (Jos 5:2-3) y el ''filo'' de una espada (Sal 89:43), una rara extensión metonímica de la piedra a la hoja afilada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6698', 'spa', 'Zur; príncipe madianita muerto por Israel; también un gabaonita en Benjamín', 'Zur, que significa ''roca'', es un nombre propio que llevan dos individuos distintos en las Escrituras. El primero fue un príncipe de Madián y padre de Cozbi, la mujer implicada en el incidente de Baal Peor; fue muerto junto con otros cuatro reyes madianitas durante la campaña de Israel (Nm 25:15; 31:8; Jos 13:21). El segundo Zur era un gabaonita que aparece en la genealogía benjaminita de Crónicas (1 Cr 8:30; 9:36). El significado del nombre, ''roca'', es un elemento teofórico común en la onomástica semítica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6699', 'spa', 'Forma, diseño o patrón arquitectónico; la estructura visible de algo, especialmente un edificio o plano', 'Se refiere a la forma, el diseño o la estructura visible de una construcción. Casi todas sus apariciones se concentran en la gran visión del templo de Ezequiel (Ez 43:11), donde Dios ordena al profeta mostrar a Israel la tsurat (''forma'') del templo para que se avergüencen de sus iniquidades y estudien su diseño. La única aparición fuera de Ezequiel se encuentra en el Salmo 49:14, donde describe la ''forma'' de los muertos consumiéndose en el Seol. El término en español ''forma'' capta bien el significado central, aunque la especificidad arquitectónica en Ezequiel le confiere un matiz técnico que va más allá de la mera ''apariencia''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6700', 'spa', 'Zuriel, líder levita; nombre que significa ''mi roca es Dios'' o ''Dios es mi roca''', 'Zuriel fue un líder levítico, jefe de la casa paterna de los meraritas durante las peregrinaciones por el desierto. Su nombre es teofórico y significa «mi roca es Dios», expresando confianza en la estabilidad y protección divinas. Es uno de tantos nombres en Números que dan testimonio de convicciones de fe, incorporando teología en la identidad personal. La Septuaginta conserva el nombre de forma reconocible, y se destaca como una figura entre los muchos que organizaron la vida cultual de Israel en el desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6701', 'spa', 'Zurisadai; ''mi roca es Shadai'', padre de Selumiel de Simeón', 'Zurisadai es un nombre compuesto teofórico que significa ''mi roca es Shadai (el Todopoderoso)''. Se le conoce únicamente como el padre de Selumiel, el líder tribal que representó a Simeón durante el censo del desierto y la dedicación del tabernáculo. Al igual que Zuar para Isacar, el nombre aparece exclusivamente en la expresión formulaica ''Selumiel hijo de Zurisadai'' en cinco pasajes de Números (1:6; 2:12; 7:36, 41; 10:19). El nombre mismo atestigua la práctica israelita antigua de incorporar títulos divinos dentro de los nombres personales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6702', 'spa', 'encender, quemar, prender fuego (causativo); los incendiaré', 'Este verbo en Hifil significa encender o prender fuego, hacer que algo arda. En Isaías 27:4, Dios dice que si espinos y zarzas se le enfrentaran, marcharía contra ellos y los quemaría juntos. Es un verbo de acción decisiva y consumidora: no se trata de un fuego accidental, sino de una incineración deliberada. La imagen es la del juicio divino como fuego que destruye por completo toda oposición, sin dejar más que cenizas. Es contundente, definitivo y total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6703', 'spa', 'deslumbrante, resplandeciente, claro, ardiente (referido al calor, viento, apariencia o habla)', 'Adjetivo que describe brillo, intensidad o claridad. Aparece con «calor» (calor resplandeciente en Isaías 18:4), «viento» (viento abrasador en Jeremías 4:11), una persona (el amado es «blanco y rubicundo» en Cantares 5:10) y el habla («hablar con claridad» en Isaías 32:4). La idea central es la de brillantez o nitidez, ya sea visual (blancura deslumbrante), térmica (calor intenso) o comunicativa (discurso claro). La palabra evoca pureza, intensidad y percepción sin obstáculos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6704', 'spa', 'reseco, deshidratado por la sed o el calor', 'Este adjetivo intensifica la idea de estar completamente seco, yendo más allá de la sed ordinaria hasta la desecación extrema. Isaías lo emplea para describir a personas tan resecas de sed que están muriendo (Is 5:13). El español «reseca» capta bien el sentido de sequedad total. Es una forma adjetival intensiva (nótese la referencia de BDB a Gesenius §84b-c) que subraya la extremidad de la condición: no meramente sediento, sino completamente marchito y consumido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6705', 'spa', 'ser deslumbrantemente blanco, resplandecer con blancura brillante', 'Este verbo describe una blancura brillante y deslumbrante, particularmente referida a la piel. El cognado siríaco sugiere claridad y resplandor, mientras que el arameo apunta al pulido. En Lamentaciones 4:7 describe la apariencia radiante de los nazareos antes de la caída de Jerusalén: su piel era «más deslumbrante que la leche», más blanca que la nieve. No se trata de un simple color blanco, sino de un resplandor luminoso que denotaba salud y vigor plenos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6706', 'spa', 'Roca desnuda, superficie rocosa expuesta y lisa, sin cobertura vegetal ni tierra', 'Término que designa una superficie de roca lisa y descubierta, desprovista de vegetación o cualquier cobertura. Ezequiel lo emplea cuatro veces en los capítulos 24 y 26: describe la peña desnuda donde la sangre fue derramada a la vista de todos (24:7-8) y profetiza que Tiro quedará como roca pelada donde se tenderán redes de pesca (26:4, 14). Nehemías 4:7 podría aludir a lugares abiertos y expuestos. La imagen transmite desolación total: roca despojada de suelo, plantas y todo refugio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6707', 'spa', 'tierra abrasada, suelo árido y reseco', 'Este sustantivo designa una tierra calcinada o reseca por el calor extremo. La raíz sugiere una aridez profunda, más allá de lo que la lluvia puede aliviar. El Salmo 68:6 lo utiliza para describir los lugares desolados donde Dios hace habitar a los rebeldes. Se trata de un terreno tan abrasado y endurecido que resulta inhóspito para cualquier forma de vida, un desierto que funciona tanto como realidad geográfica como expresión del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6709', 'spa', 'hedor, olor fétido de putrefacción', 'Este sustantivo se refiere a un olor repulsivo, especialmente el de la descomposición. Joel 2:20 lo emplea en paralelo con otro término para hedor al describir el olor del ejército invasor del norte cuando Dios lo expulsa. La duplicación de palabras para el mal olor —«su pestilencia» junto a «su hedor»— subraya la putrefacción total de la horda derrotada. La imagen evoca cadáveres descomponiéndose al sol, una representación gráfica de la derrota absoluta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6710', 'spa', 'regiones abrasadas, lugares azotados por la sequía', 'Este sustantivo plural describe zonas de sequía extrema o tierra calcinada. Isaías 58:11 lo utiliza en la promesa de Dios de satisfacer las necesidades de su pueblo incluso en los lugares más áridos. La raíz se vincula con el calor abrasador y el suelo reseco. Se refiere a regiones donde el agua escasea desesperadamente, terrenos no solo secos sino quemados por un calor intenso. En este contexto, la provisión divina en tales parajes resalta la fidelidad de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6711', 'spa', 'Asociado para siempre con el patriarca Isaac, cuyo nombre mismo (Yitsjaq, ''él ríe'') encarna el alcance de este verbo. En su forma Qal describe la risa', 'Asociado para siempre con el patriarca Isaac, cuyo nombre mismo (Yitsjaq, ''él ríe'') encarna el alcance de este verbo. En su forma Qal describe la risa incrédula de Sara ante la promesa de un hijo (Gn 18:12-15) y la risa gozosa de Abraham (Gn 17:17). El Piel se intensifica hacia la burla: Ismael ''burlándose'' del joven Isaac (Gn 21:9), Lot pareciendo ''como quien bromea'' ante sus yernos (Gn 19:14) y la esposa de Potifar acusando a José (Gn 39:14, 17). El español burlarse y el alemán Spott treiben captan este matiz despectivo. El mismo Piel también produce un sentido más ligero de juego festivo, como cuando Israel se levantó ''a jugar'' ante el becerro de oro (Éx 32:6) y cuando hicieron a Sansón ''divertir'' a los filisteos (Jue 16:25).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6713', 'spa', 'gris rojizo, leonado (referido a lana, o posible topónimo)', 'Este sustantivo parece describir un color de lana o posiblemente un nombre de lugar. El sentido principal es un tono gris rojizo o leonado, mencionado en Ezequiel 27:18 dentro del catálogo de mercancías comerciadas por Damasco. Algunos eruditos sugieren que podría tratarse de «lana de Zahar» (una localidad), aunque esto es debatido. El contexto de artículos de lujo sugiere un color distintivo y valioso de lana, posiblemente resultado de un procesamiento especial o una procedencia regional específica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6714', 'spa', 'Zohar; padre de Efrón el heteo; también un hijo de Simeón y un judahita', 'Zohar, cuyo significado es ''leonado'' o ''blanco rojizo'', es un nombre propio compartido por tres individuos bíblicos. El más destacado es el padre de Efrón el heteo, de quien Abraham compró la cueva de Macpela (Gn 23:8; 25:9). Un segundo Zohar fue hijo de Simeón, que descendió a Egipto con Jacob (Gn 46:10; Éx 6:15). Un tercero aparece en la genealogía de Judá en Crónicas (1 Cr 4:7). La LXX traduce el nombre como Saar en todas sus apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6715', 'spa', 'leonado, de color claro (referido a asnos)', 'Este adjetivo describe el color del pelaje de los asnos y aparece exclusivamente en Jueces 5:10, dentro del cántico de Débora. La raíz se relaciona con tonalidades rojizas, leonadas o claras. La expresión «los que cabalgáis sobre asnas leonadas» se dirige a la clase gobernante o adinerada, ya que los asnos de pelaje más claro eran aparentemente muy apreciados. El sentido apunta a una coloración distintiva y deseable que denotaba estatus o calidad de cría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6716', 'spa', 'Nave, embarcación marítima', 'Esta palabra designa naves o embarcaciones de alta mar. Parece ser un préstamo del egipcio, reflejo del vocabulario marítimo internacional del antiguo Cercano Oriente. Números 24:24 menciona naves de Quitim en el oráculo de Balaam. Isaías 33:21 habla de «naves majestuosas» que no navegarán por las aguas de Jerusalén. Ezequiel 30:9 describe mensajeros que parten en naves para advertir a Cus. Daniel 11:30 profetiza que «naves de Quitim» vendrán contra el rey del norte. Los contextos suelen evocar poder naval y alcance internacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6717', 'spa', 'Siba — siervo de la casa de Saúl y administrador de las propiedades de Mefiboset en las narrativas de David', 'Siba — siervo de la casa de Saúl y administrador de las propiedades de Mefiboset en las narrativas de David');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6718a', 'spa', 'צַיִד es la palabra que llena la tienda de Isaac con el aroma de caza silvestre. Enraizada en el acto de cazar, designa con mayor frecuencia la presa ', 'צַיִד es la palabra que llena la tienda de Isaac con el aroma de caza silvestre. Enraizada en el acto de cazar, designa con mayor frecuencia la presa misma —el animal capturado y traído a casa como alimento. Las narraciones patriarcales del Génesis le dan vida vívida: Isaac amaba a Esaú ''porque la caza estaba en su boca'' (Gn 25:28), y la dramática escena del engaño gira en torno a la preparación de צַיִד para el padre anciano (Gn 27:5-33). El español caza y el francés chassant oscilan entre ''cacería'' y ''presa'', igual que el hebreo, mientras que el alemán Wildbret (''venado'') se centra en la carne. El sentido más raro de actividad aparece memorablemente en Génesis 10:9, donde Nimrod es gibbor tsayid, ''un poderoso cazador delante de Jehová'', descripción tan famosa que se convirtió en proverbio. Levítico 17:13 extiende el término a cualquier animal o ave cazados cuya sangre debe ser debidamente derramada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6718b', 'spa', 'Provisión, alimento, sustento (especialmente para viaje o necesidad)', 'Palabra que designa alimento o provisiones, en particular los suministros que se llevan para un viaje o que se necesitan para el sustento. Josué 9:5, 14 se refiere a las provisiones que los gabaonitas afirmaban haber tomado para su supuesto largo camino. Nehemías 13:15 menciona alimentos que se introducían en Jerusalén en sábado. Job 38:41 habla de Dios proveyendo alimento al cuervo. El Salmo 132:15 promete abundante provisión para Sion. El término enfatiza el sustento y el abastecimiento, sobre todo en contextos de travesía o necesidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6719', 'spa', 'cazadores', 'Este sustantivo plural designa a quienes cazan o atrapan animales, derivado de la raíz que significa cazar o poner trampas. Jeremías 16:16 lo emplea en una metáfora impactante: Dios enviará primero pescadores y luego cazadores para buscar a los israelitas exiliados. Los cazadores representan la exhaustividad de la búsqueda divina: ningún escondite será suficiente. Las traducciones multilingües coinciden uniformemente en el sentido ocupacional directo de «cazadores».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6720', 'spa', 'Provisiones o víveres para un viaje; también caza o presa traída como alimento', 'Sustantivo femenino centrado en la idea de alimento adquirido para el sustento, especialmente para un viaje. En su uso predominante se refiere a las provisiones preparadas para una travesía — el pan y los suministros que los hermanos de José llevaron desde Egipto (Gn 42:25; 45:21) o la masa sin levadura que Israel sacó de Egipto (Éx 12:39). El árabe zād y el coreano 양식 denotan específicamente ''provisiones de viaje'', confirmando este sentido central. Un segundo sentido distinto aparece en Gn 27:3, donde significa caza — la presa que Esaú debe atrapar para Isaac. El español ''caza'' y el alemán Wildbret (''venado'') hacen esta distinción inequívoca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6721', 'spa', 'Sidón — la antigua ciudad costera fenicia; también el hijo primogénito de Canaán en la Tabla de las Naciones', 'Sidón — la antigua ciudad costera fenicia; también el hijo primogénito de Canaán en la Tabla de las Naciones');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6722', 'spa', 'Sidonio(s) — adjetivo gentilicio para los habitantes de la ciudad fenicia de Sidón, a veces designando a los fenicios en general', 'Sidonio(s) — adjetivo gentilicio para los habitantes de la ciudad fenicia de Sidón, a veces designando a los fenicios en general');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6723', 'spa', 'Sequedad, aridez: la cualidad reseca de tierra árida; una región desértica seca; un período prolongado de escasez de agua', 'Sequedad, aridez: la cualidad reseca de tierra árida; una región desértica seca; un período prolongado de escasez de agua');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6725', 'spa', 'poste indicador, marcador, monumento; un indicador físico usado para navegación, conmemoración o identificación', 'El término se refiere a marcadores o monumentos—señales físicas que comunican información. En 2 Reyes 23:17, es una lápida que marca la tumba de un profeta. Jeremías 31:21 pide establecer marcadores de camino o postes indicadores para recordar el camino a casa desde el exilio. Ezequiel 39:15 describe marcadores colocados junto a huesos humanos encontrados en la tierra. La función cambia de conmemoración a navegación a identificación, pero la idea central permanece: una señal visible comunicando a quienes pasan. La evidencia multilingüe varía—algunos ven nombres propios (francés ''Sion'', alemán ''Zion''), mientras que la mayoría reconoce marcadores o monumentos comunes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6726', 'spa', 'Sion — la colina fortificada de Jerusalén, que se extiende para designar la ciudad santa, el monte del templo y el pueblo de Dios', 'Sion (tsiyyon) designaba originalmente la fortaleza jebusea sobre la cresta suroriental de Jerusalén, conquistada por David y rebautizada como Ciudad de David (2 S 5:7). Con el tiempo, el nombre se expandió hasta abarcar el monte del Templo, la ciudad entera y, por metonimia poética, al pueblo de Dios mismo. Los profetas favorecen especialmente a Sion como símbolo teológico: ''hija de Sion'' personifica a Jerusalén en su vulnerabilidad y esperanza (Is 1:8; Zac 9:9). A lo largo de sus 154 ocurrencias, el nombre porta un peso de elección divina, morada y restauración futura que ningún mero topónimo podría transmitir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6727', 'spa', 'Ziha; nombre personal de un supervisor de siervos del templo, cuyos descendientes regresaron del exilio', 'Ziha fue un supervisor de los Netinim (siervos del templo) cuya línea familiar se menciona en los registros postexílicos. Los ''hijos de Ziha'' aparecen tanto en las listas de Esdras como de Nehemías de exiliados que regresaron, indicando un grupo familiar reconocido que mantuvo responsabilidades de servicio del templo. Nehemías 11:21 identifica al mismo Ziha como supervisor de los Netinim. El nombre aparece en tres pasajes documentando la organización y genealogía de la comunidad de restauración. La evidencia interlingüística muestra variaciones menores de ortografía (Siha, Sijá, Tsicha) pero reconocimiento consistente de este como un nombre personal vinculado a la administración del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6728', 'spa', 'Criatura del desierto o bestia salvaje; por extensión, morador del desierto o habitante del yermo', 'Presente exclusivamente en oráculos proféticos de desolación, tsiyyi evoca la fauna inquietante que reclama las ciudades abandonadas. Isaías 13:21 y 34:14 enumeran estas criaturas junto a bestias aullantes (iyyim), pintando ruinas donde solo merodean chacales y gatos salvajes. La identificación zoológica exacta sigue siendo incierta; cognados árabes sugieren un gato montés o animal desértico aullador. En el Salmo 72:9 la palabra puede inclinarse hacia moradores humanos del desierto que se postran ante el rey, y en el Salmo 74:14 Dios entrega al Leviatán como alimento ''al pueblo del desierto''. El español distingue con claridad: ''bestias del desierto'' para el sentido animal y ''moradores del desierto'' para el humano.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6729', 'spa', 'argolla, collar de sujeción o cepo', 'Este sustantivo designa un instrumento de castigo y humillación pública, probablemente un collar de madera o cepo que inmovilizaba a los prisioneros. Jeremías 29:26 lo menciona junto al «cepo» como herramienta para someter a los profetas considerados locos. El contexto muestra que las autoridades del templo lo empleaban para controlar y avergonzar a quienes se tenían por alborotadores. El término apunta a un dispositivo de sujeción física que restringía el movimiento y señalaba públicamente al condenado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6730', 'spa', 'Sior, una ciudad en la región montañosa de Judá', 'Este nombre propio identifica una ciudad situada en la zona montañosa cercana a Hebrón, incluida entre las herencias tribales de Judá en Josué 15:54. La identificación moderna la sitúa en Ṣâʿîr, aproximadamente ocho kilómetros al norte-noreste de Hebrón según la geografía de Buhl. La Septuaginta la transcribe de diversas formas, como Σωρθ o Σιωρ. Las traducciones multilingües conservan el nombre en transliteración, reflejando su carácter de designación geográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6731a', 'spa', 'Una palabra que tiende un puente entre el jardín y el santuario. Con mayor frecuencia denota una flor o capullo: Isaías 40:6-8 la emplea en el famoso ', 'Una palabra que tiende un puente entre el jardín y el santuario. Con mayor frecuencia denota una flor o capullo: Isaías 40:6-8 la emplea en el famoso pasaje donde ''la hierba se seca, la flor se marchita, pero la palabra de nuestro Dios permanece para siempre''. Números 17:8 relata la vara de Aarón brotando con flores (צִיץ), y 1 Reyes 6:18-35 describe ornamentos florales tallados en todo el templo de Salomón. Pero la misma palabra también designa la placa de oro sujeta al turbante del sumo sacerdote (Éx 28:36; 39:30; Lv 8:9), inscrita con ''Santo a Jehová''. El árabe distingue claramente ambos sentidos: zuhurin (''flores'') para el sentido botánico y safihata (''una placa de metal'') para la diadema sacerdotal, confirmando que son significados genuinamente distintos y no una extensión metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6731b', 'spa', 'alas (posiblemente plumas de ala; significado incierto)', 'El significado de este sustantivo es debatido, pero la interpretación más aceptada es «alas» en sentido colectivo. Jeremías 48:9 contiene la difícil expresión «dad alas a Moab», que la mayoría de los estudiosos entiende como un llamado a huir velozmente, como si tuviese alas. El cognado arameo significa ala o aleta, lo cual respalda esta lectura. Sin embargo, la Septuaginta tradujo «señales», lo que llevó a algunos a proponer «poste indicador», y Perles sugirió leer «plumas». La interpretación de alas se ajusta mejor a la imaginería de huida del contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6732', 'spa', 'Sis, nombre de una cuesta o paso de montaña cerca del mar Muerto', 'Este topónimo aparece en 2 Crónicas 20:16, donde designa una cuesta o paso por el que los ejércitos invasores subían desde la región del mar Muerto. La «cuesta de Sis» fue la ruta por la que moabitas y amonitas avanzaron contra Josafat. La geografía de Buhl la identifica con el Wady Ḥaṣâṣâ y la meseta Ḥaṣâṣâ al norte de En-gadi. Las versiones de la Septuaginta varían, pero la ubicación corresponde claramente a un accidente geográfico reconocido en la topografía de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6733', 'spa', 'Flor, capullo (en estado constructo)', 'Este sustantivo designa una flor o capullo, y aparece en Isaías 28:4 en forma constructa. El versículo habla de «la flor marchita» de la gloria de Efraín, empleando una imagen floral para representar algo bello pero efímero. La metáfora capta con precisión la fragilidad: lo que florece con esplendor pronto se marchita. La raíz es la misma que la de la palabra más común para flor o capullo en hebreo bíblico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6734', 'spa', 'Fleco, borla (en vestidura); mechón de cabello', 'Esta palabra tiene dos usos relacionados: las borlas rituales en los bordes de las vestiduras y un mechón de cabello en la frente. Números 15:38-39 ordena tres veces a Israel hacer flecos en las esquinas de sus vestiduras como recordatorio de los mandamientos de Dios; estos se convirtieron en los tzitzit que los judíos observantes siguen usando. Ezequiel 8:3 emplea el mismo término para un mechón de cabello de la frente del profeta, por el cual fue levantado en una visión. Ambos usos comparten la idea de algo que cuelga o sobresale de manera prominente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6735a', 'spa', 'Enviado, mensajero o embajador despachado en misión oficial, ya sea humana o divina.', 'Designa a un enviado o mensajero oficial despachado en una misión diplomática o profética. En Jeremías 49:14 y Abdías 1, el enviado es mandado por el SEÑOR mismo para convocar a las naciones contra Edom. Isaías 18:2 describe mensajeros veloces enviados por mar desde Cus, mientras que Isaías 57:9 condena a Israel por enviar sus propios emisarios a potencias extranjeras. En Proverbios, el término adquiere un sentido más general: un mensajero fiel refresca el alma como nieve fría en tiempo de siega (Prov 25:13), mientras que un mensajero malvado cae en desgracia (Prov 13:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6735b', 'spa', 'Gozne, bisagra (de una puerta)', 'Este sustantivo designa el pivote o gozne sobre el cual gira una puerta. Proverbios 26:14 lo emplea en un símil memorable que compara al perezoso dando vueltas en su cama con una puerta girando sobre sus goznes: ambos rotan en el mismo sitio sin ir a ninguna parte. La imagen capta con agudeza la actividad inútil: mucho movimiento, ningún progreso. Se refiere al mecanismo que permite el movimiento rotatorio de la puerta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6735c', 'spa', 'dolores agudos, retorcimientos; angustia convulsiva semejante a los dolores de parto', 'Este sustantivo designa dolores agudos y convulsivos, especialmente aquellos comparados con la agonía del parto. En 1 Samuel 4:19, la esposa de Finees entra literalmente en dolores de parto al enterarse de la captura del arca. Isaías emplea la imagen metafóricamente para describir el terror que se apodera de Babilonia (13:8) y del propio profeta ante la visión del juicio (21:3). Daniel 10:16 extiende el uso para describir los efectos físicos abrumadores de la angustia visionaria. La raíz sugiere retorcimiento o contorsión, capturando la convulsión corporal involuntaria del dolor extremo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6737', 'spa', 'Aprovisionarse, proveerse de alimento para un viaje', 'Este verbo denominativo, derivado del sustantivo que significa «provisiones», significa proveerse de alimento o tomar bastimentos para un viaje. En Josué 9:4 y 9:12 se usa para describir el engaño de los gabaonitas, quienes afirmaron haberse aprovisionado hacía mucho tiempo para un viaje lejano, mostrando pan reseco como prueba. El verbo aparece en forma hitpael, indicando una acción reflexiva: se proveyeron a sí mismos. El sentido fundamental es el acto de tomar provisiones para el camino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6738', 'spa', 'Sustantivo hebreo de rica estratificación que abarca lo físico y lo metafórico. En su uso más frecuente, צֵל retrata la presencia protectora de Dios —', 'Sustantivo hebreo de rica estratificación que abarca lo físico y lo metafórico. En su uso más frecuente, צֵל retrata la presencia protectora de Dios — ''la sombra del Omnipotente'' (Sal 91:1), ''la sombra de tus alas'' (Sal 17:8) — donde la sombra que resguarda del sol abrasador se convierte en una poderosa imagen de refugio divino. En sentido literal designa la sombra proyectada por árboles, rocas o un reloj de sol (2 R 20:9-11). La literatura sapiencial explota un tercer matiz: la vida pasa ''como una sombra'' (1 Cr 29:15; Sal 144:4), captando la brevedad y la inconsistencia de los días humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6740', 'spa', 'asar; cocinar carne con fuego directo o calor, a diferencia de hervir', 'El verbo significa asar carne—cocinar con fuego en lugar de agua. En 1 Samuel 2:15, los adoradores quieren dar al sacerdote carne cruda ''para asar'' en vez de porciones hervidas. Isaías 44:16, 19 satiriza la fabricación de ídolos: la misma madera asa carne para la cena y se convierte en un dios para adorar. La distinción entre asar y hervir era ritualmente significativa (Éxodo 12:8-9 requiere el cordero pascual asado, no hervido). La evidencia multilingüe es directa: ''asar'' en todos los idiomas, con formas verbales indicando acción. Este es vocabulario culinario básico con matices teológicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6741', 'spa', 'Zila; nombre personal de la esposa de Lamec en la genealogía cainita', 'Zila fue una de las dos esposas de Lamec mencionadas en Génesis 4. El nombre aparece tres veces en la narrativa de la familia de Lamec, que incluye la primera bigamia registrada y la jactancia violenta de Lamec. Zila dio a luz a Tubal-caín (el primer trabajador de metales) y Naama. El nombre puede derivar de la raíz para ''sombra'', aunque el texto no explica su significado. Las representaciones translingüísticas son consistentes (Tsillah, Tsilá, Zilla), tratando esto como un nombre propio sencillo de la genealogía antediluviana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6743a', 'spa', 'Irrumpir, venir con poder; del empoderamiento repentino del Espíritu, fuego que estalla o movimiento físico veloz.', 'Uno de los verbos más vívidos de la Biblia hebrea, usado principalmente para describir al Espíritu de YHWH irrumpiendo sobre personas para capacitarlas para hazañas extraordinarias. Sansón despedaza un león cuando el Espíritu ''vino con poder'' sobre él (Jue 14:6), y Saúl es transformado cuando el Espíritu ''vino poderosamente'' sobre él en Guibeá (1 S 10:10). La expresión española ''vino con poder'' capta hermosamente ese descenso repentino e irresistible. La raíz se extiende metafóricamente al fuego que estalla (Am 5:6) y literalmente a soldados que cruzan velozmente el Jordán (2 S 19:17).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6743b', 'spa', 'Verbo de éxito y florecimiento que abarca desde la casa de José en Egipto hasta las visiones de Daniel sobre reyes en guerra. En sus formas intransiti', 'Verbo de éxito y florecimiento que abarca desde la casa de José en Egipto hasta las visiones de Daniel sobre reyes en guerra. En sus formas intransitivas del Qal y el Hifil describe personas, planes e incluso ''el propósito de Yahvé'' que prospera (Is 53:10). El Hifil causativo añade una capa teológica: Dios es quien ''hace prosperar,'' como confiesa el siervo de Abraham cuando su misión tiene éxito (Gn 24:21, 40, 42). Un tercer sentido, más pragmático, aparece en Jeremías y Ezequiel, donde objetos arruinados ''ya no sirven'' para nada (Jer 13:7, 10) — el español ''servir'' y la pregunta ''¿Servirá?'' captan bien este significado funcional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6744', 'spa', 'Prosperar, tener éxito, hacer prosperar (arameo, Haf''el)', 'Verbo arameo (en la conjugación Haf''el) que significa prosperar, tener éxito o hacer prosperar a alguien. Daniel 3:30 relata que Nabucodonosor «promovió» (hizo prosperar) a Sadrac, Mesac y Abednego. Daniel 6:28 informa que Daniel «prosperó» durante los reinados de Darío y Ciro. Esdras 5:8 describe la obra del templo como algo que «progresa rápidamente» (prospera en sus manos). Esdras 6:14 señala que los ancianos judíos «prosperaron» en la construcción. El término subraya el éxito, el avance y la bendición divina sobre los emprendimientos humanos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6745', 'spa', 'Olla, sartén (recipiente para cocinar)', 'Este sustantivo designa un tipo de recipiente para cocinar, y aparece en la descripción de la preparación de las ofrendas de Pascua en 2 Crónicas 35:13. Se menciona junto a otros utensilios como ollas y calderos. El contexto muestra que se empleaban diversos recipientes para cocinar rápidamente la carne de los sacrificios y repartirla al pueblo. La forma plural indica que eran utensilios de uso habitual en la preparación de alimentos a gran escala durante las festividades.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6746', 'spa', 'vasija, recipiente pequeño', 'Este sustantivo designa una vasija o recipiente pequeño. Aparece en 2 Reyes 2:20, cuando Eliseo pide «una vasija nueva» para colocar sal y purificar las aguas de Jericó. La especificación de que debía ser nueva sugiere importancia ceremonial: un recipiente sin uso previo para un acto milagroso. Se trata de un objeto portátil y de tamaño modesto, distinto de las tinajas grandes de almacenamiento, con un propósito específico y simbólico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6747', 'spa', 'plato, fuente; vasija poco profunda usada para servir o comer alimentos', 'Este sustantivo se refiere a un plato o fuente—un utensilio doméstico para alimentos. 2 Reyes 21:13 lo usa en un símil vívido: Dios limpiará a Jerusalén como quien limpia un plato, volteándolo boca abajo. Proverbios 19:24 y 26:15 satirizan al perezoso que mete su mano en el plato pero es demasiado flojo para llevársela a la boca. La simplicidad doméstica del objeto lo hace perfecto para imágenes proverbiales. Las traducciones translingüísticas reconocen uniformemente esto como un plato o tazón, con los artículos en español y alemán (''el plato'', ''der dish'') marcando referencia definida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6748', 'spa', 'asado; carne o comida preparada con fuego, particularmente en contextos rituales', 'Este adjetivo y sustantivo describe carne asada—específicamente carne cocinada con fuego en lugar de hervida en agua. Éxodo 12:8-9 prescribe el cordero pascual como ''asado al fuego'', contrastando explícitamente con hervir. Isaías 44:16 habla de un ''asado'' como la comida cocinada sobre el fuego del cual también se tallan ídolos. La importancia ritual es primordial: asar era la preparación ordenada para la Pascua, distinguiéndola de comidas ordinarias. La evidencia translingüística muestra formas tanto adjetivales (''asado'') como nominales (''un asado''), reflejando la doble función del hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6749', 'spa', 'hundirse, sumergirse (en el agua)', 'Este verbo significa hundirse o quedar sumergido, especialmente en el agua. Éxodo 15:10 lo emplea en el Cántico del Mar, describiendo cómo el ejército del faraón «se hundió como plomo en las aguas impetuosas» cuando Dios sopló su aliento sobre ellos. El símil con el plomo enfatiza la rapidez e irreversibilidad del hundimiento: sin forcejeo ni flotación, solo una caída inmediata hacia el fondo. Los cognados en otras lenguas semíticas abarcan ideas de hundirse, posarse y hasta flotar, mostrando un campo semántico amplio relacionado con el movimiento en el agua.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6750', 'spa', 'retumbar, zumbar (de oídos); temblar, estremecerse (de labios); susurrar (de espíritus)', 'Verbo onomatopéyico que describe diversos sonidos y sensaciones de vibración o resonancia. Aplicado a los oídos, significa retumbar o zumbar ante noticias espantosas (1 S 3:11; 2 R 21:12; Jer 19:3). Aplicado a los labios, describe el temblor de terror (Hab 3:16). La raíz evoca un movimiento vibratorio rápido y repetido, capturando la respuesta física ante el impacto o el espanto. El sonido que sugiere es agudo, breve e inquietante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6752', 'spa', 'sombra, sombras (protección del sol; también sombras del atardecer)', 'Esta palabra significa principalmente sombra, a menudo con connotaciones de protección, frescura o paso del tiempo. Aparece en expresiones como «sombras de la tarde» (que se alargan al caer el día), «sombra de las ramas» (que ofrecen cobijo) y «sombra de una roca» (protección refrescante). El término posee tanto sentido literal (sombra real del sol) como extensiones metafóricas: refugio, fugacidad de la vida y amparo. Las sombras pueden representar consuelo y resguardo, o bien la cercanía de la oscuridad y el peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6753', 'spa', 'Hazelelponi, nombre femenino en la genealogía de Judá', 'Este nombre propio pertenece a una mujer en la genealogía de Judá (1 Crónicas 4:3). Su etimología sugiere algo como «dame sombra, tú que te vuelves hacia mí», aunque las interpretaciones varían. La Septuaginta ofrece lecturas muy divergentes, lo cual indica incertidumbre textual. Como nombre femenino que aparece en listas genealógicas predominantemente masculinas, su inclusión preserva la memoria de una mujer lo suficientemente importante como para ser registrada en los anales familiares de Judá, aunque no se conoce nada más sobre ella.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6754', 'spa', 'Imagen, semejanza o ídolo; una representación física de algo, la semejanza divina en la humanidad, o un mero fantasma', 'Imagen, semejanza o ídolo; una representación física de algo, la semejanza divina en la humanidad, o un mero fantasma');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6755', 'spa', 'Imagen, estatua, forma — una representación física o semejanza, especialmente la estatua del sueño de Nabucodonosor en Daniel 2-3 y la imagen de Dios ', 'Imagen, estatua, forma — una representación física o semejanza, especialmente la estatua del sueño de Nabucodonosor en Daniel 2-3 y la imagen de Dios en la humanidad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6756b', 'spa', 'Zalmón, uno de los guerreros valientes de David', 'Este nombre propio identifica a uno de los guerreros de élite de David, incluido en la lista de 2 Samuel 23:28. El pasaje paralelo de 1 Crónicas 11:29 lo llama Ilai, lo que sugiere que se trata de un nombre alternativo para la misma persona o de una variante textual. La Septuaginta también presenta lecturas diversas. Zalmón figura entre los «treinta» valientes que conformaban las fuerzas especiales de David, guerreros distinguidos reconocidos individualmente por sus hazañas militares.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6757', 'spa', 'Oscuridad profunda, sombra de muerte — tiniebla intensa e impenetrable usada poéticamente para el peligro mortal y el misterio divino', 'Oscuridad profunda, sombra de muerte — tiniebla intensa e impenetrable usada poéticamente para el peligro mortal y el misterio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6759', 'spa', 'Zalmuna — rey madianita capturado y ejecutado por Gedeón junto con Zeba tras la gran derrota', 'Zalmuna (צַלְמֻנָּע) es el nombre propio de uno de los dos reyes de Madián — siempre emparejado con Zeba — que fueron perseguidos, capturados y ejecutados por Gedeón tras la derrota decisiva del ejército madianita. El nombre posiblemente derive de צֵל (''sombra'') + מָנַע (''retener''), quizás significando ''la sombra es retenida'', aunque su etimología sigue siendo incierta. La persecución de Zeba y Zalmuna por parte de Gedeón al otro lado del Jordán, su encuentro con los hombres hostiles de Sucot y Penuel, y la ejecución personal de ambos reyes conforman una de las narrativas más vívidas de Jueces 8:5-21. El Salmo 83:12 invoca a Zeba y Zalmuna como enemigos derrotados por excelencia: ''Pon a sus príncipes como a Zeba y Zalmuna''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6760', 'spa', 'cojear, caminar renqueando (por lesión o discapacidad)', 'Verbo que describe la acción de cojear o caminar con paso impedido. Génesis 32:31 explica por qué los israelitas no comen el tendón del muslo: porque Jacob iba «cojeando de su cadera» tras luchar con el ser divino. Miqueas y Sofonías usan el participio femenino como sustantivo para «la coja», personificando al exilio de Judá como una oveja que renquea y que Dios recogerá y restaurará (Mi 4:6-7; Sof 3:19). La palabra evoca tanto la discapacidad física como la vulnerabilidad metafórica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6761', 'spa', 'tropiezo, cojera, calamidad; inestabilidad física usada figurativamente para desastre o vulnerabilidad', 'El sustantivo denota tropiezo o cojera, usado figurativamente para calamidad y vulnerabilidad. Los Salmos hablan de estar ''listo para tropezar'' (38:17) y enemigos regocijándose ''en mi tropiezo'' (35:15)—momentos de debilidad cuando los adversarios atacan. Job 18:12 advierte que ''la ruina está lista para su tropiezo''. Jeremías 20:10 menciona ''vigilantes de mi tropiezo''—aquellos esperando que el profeta falle. La imagen física de perder el equilibrio se vuelve metáfora de desastre, caída y oportunismo de enemigos. La evidencia translingüística muestra traducciones tanto literales (''stumbling'', ''cojear'') como metafóricas (''calamidad'', ''shadow'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6763', 'spa', 'Costilla, lado, cámara lateral; del cuerpo humano, lados de objetos, aposentos laterales del templo, tablones y laderas', 'Costilla, lado, cámara lateral; del cuerpo humano, lados de objetos, aposentos laterales del templo, tablones y laderas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6764', 'spa', 'Zalaf, padre de un constructor del muro bajo Nehemías', 'Este nombre propio identifica al padre de uno de los constructores del muro de Jerusalén en Nehemías 3:30. El nombre podría derivar de una palabra que designa la planta de alcaparra, según el hebreo rabínico. El hijo de Zalaf participó en la reconstrucción de las murallas de Jerusalén después del exilio, y su inclusión en el registro detallado de constructores demuestra que esta familia formaba parte de la comunidad restaurada. La Septuaginta conserva el nombre con las adaptaciones típicas al griego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6765', 'spa', 'Zelofejad, hombre de Manasés cuyas cinco hijas obtuvieron derechos de herencia para las mujeres en Israel', 'Nombre de un hombre de la tribu de Manasés que murió en el desierto sin dejar hijos varones, solo cinco hijas: Majlá, Noa, Joglá, Milca y Tirsa. Su audaz petición ante Moisés estableció el precedente legal de que las hijas pueden heredar cuando no hay heredero varón (Nm 27:1-7). El caso fue lo suficientemente significativo como para revisarse en Números 36, donde se equilibró la preservación territorial de las tribus con el nuevo derecho de herencia. Las hijas de Zelofejad se convirtieron en un hito de la jurisprudencia bíblica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6766', 'spa', 'Zelzá, topónimo en el territorio de Benjamín', 'Este topónimo aparece en 1 Samuel 10:2, donde Samuel indica a Saúl que encontrará a dos hombres «junto a Zelzá, en la frontera de Benjamín», cerca de la tumba de Raquel. Sin embargo, el texto probablemente está corrupto: los estudiosos señalan que la ubicación es incierta y algunos proponen leer «desde Zelá» (otra ciudad de Benjamín). La Septuaginta ofrece lecturas variantes. A pesar de las dificultades textuales, la narración lo presenta como un punto de referencia que Saúl reconocería cerca del sepulcro de Raquel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6767a', 'spa', 'zumbido, rumor de alas (de insectos)', 'Este sustantivo designa el zumbido o rumor producido por alas que se mueven rápidamente, en particular las de insectos. Isaías 18:1 describe «la tierra del zumbido de alas», refiriéndose probablemente a Etiopía o a una región con abundancia de insectos en enjambres. La expresión construida «zumbido de alas» crea una imagen auditiva de innumerables insectos en vuelo. Se trata de una palabra onomatopéyica que capta el sonido característico de densas poblaciones de insectos, aunque los intérpretes debaten si debe entenderse de forma literal (langostas, moscas) o simbólica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6767b', 'spa', 'arpón, lanza de pesca', 'Este sustantivo designa un arma utilizada para lancear peces grandes o criaturas marinas. Aparece en Job 40:31 (41:7 en versiones inglesas), dentro del desafío de Dios sobre la captura de Leviatán: «¿Podrás llenar su piel de arpones?», subrayando la invulnerabilidad de la criatura ante las armas de pesca convencionales. Su etimología se relaciona con el silbido o zumbido que produce la lanza al ser arrojada. Se trata de un equipo especializado para la caza de grandes presas acuáticas, distinto de las redes o los anzuelos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6767c', 'spa', 'langosta (de tipo zumbador), grillo', 'Este sustantivo identifica un tipo de langosta o grillo, llamado así por el zumbido que produce. Deuteronomio 28:42 lo incluye entre las maldiciones del pacto: «la langosta zumbadora se apoderará de todos tus árboles y cosechas». Los cognados en acadio y arameo también designan insectos que chirrían o zumban. Aunque la especie exacta es incierta, la característica definitoria es el sonido: un ruido persistente e invasivo que acompaña la devastación agrícola. Es uno de varios términos hebreos para la langosta, cada uno distinguiendo posiblemente tipos o etapas de vida del insecto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6767d', 'spa', 'címbalos; instrumentos de percusión que producen un sonido resonante o metálico, usados en la adoración', 'Este sustantivo plural se refiere a los címbalos—instrumentos musicales de percusión que producen un sonido metálico y resonante. En 2 Samuel 6:5 se describe a David e Israel celebrando delante del arca con címbalos y otros instrumentos. El Salmo 150:5 llama a alabar a Dios con ''címbalos resonantes'' y ''címbalos de júbilo'', distinguiendo tipos según la calidad del sonido. La palabra deriva de una raíz que sugiere sonidos metálicos o resonantes. En diversos idiomas, el término se reconoce consistentemente como címbalos (francés ''cymbales'', alemán ''Zimbeln''), mostrando un referente instrumental claro usado en contextos de adoración gozosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6770', 'spa', 'Tener sed; del deseo físico de agua o del anhelo espiritual figurado por Dios.', 'Describe la experiencia humana fundamental de la sed, tanto física como espiritual. En sentido literal, aparece en narrativas dramáticas del desierto: Israel en Refidim exigiendo agua (Éx 17:3), Sansón al borde del desfallecimiento tras derrotar a los filisteos (Jue 15:18) y Rut en los campos de siega de Belén (Rut 2:9). Su uso más memorable es figurado: ''Mi alma tiene sed de Dios, del Dios vivo'' (Sal 42:3; cf. 63:1), donde la necesidad corporal se convierte en metáfora de un anhelo espiritual desesperado. El español ''tiene sed'' y el cognado árabe transmiten la misma urgencia visceral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6771', 'spa', 'Sediento; describe a una persona o tierra que carece de agua, a veces en sentido figurado de anhelo espiritual.', 'Adjetivo que describe el estado de necesitar agua, frecuentemente emparejado con ra''ev (''hambriento'') para retratar la privación humana (2 Sam 17:29; Prov 25:21; Sal 107:5). Isaías extiende la palabra hacia una metáfora poderosa: los sedientos son invitados a venir a las aguas gratuitamente (Isa 55:1), y Dios promete derramar agua sobre la tierra sedienta y su Espíritu sobre la descendencia de Israel (Isa 44:3). El español ''sediento'' conserva tanto el registro literal como el figurado. Deuteronomio 29:19 lo emplea de manera singular en la expresión proverbial ''arrasar lo regado junto con lo sediento''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6772', 'spa', 'Sed; el deseo físico intenso de agua, frecuentemente emparejado con el hambre como señal de privación o juicio divino. Denota el deseo corporal doloro', 'Sed; el deseo físico intenso de agua, frecuentemente emparejado con el hambre como señal de privación o juicio divino. Denota el deseo corporal doloroso de agua, apareciendo con mayor frecuencia en contextos de sufrimiento en el desierto, asedio y juicio profético. En Éxodo 17:3 los israelitas claman en el desierto, mientras que Deuteronomio 28:48 enumera la sed junto con el hambre, la desnudez y la carencia como consecuencias de la maldición del pacto. Oseas y Amós extienden la imagen: Amós 8:11 habla de una sed no de agua sino de la palabra del SEÑOR, transformando una necesidad visceral en anhelo espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6773', 'spa', 'sequedad, estado de resequedad por la sed', 'Este sustantivo describe la condición reseca de la garganta a causa de la sed. Aparece en Jeremías 2:25, dentro de la reprensión de Dios a Israel por su adulterio espiritual: «Guarda tu garganta de la sequedad», es decir, deja de perseguir frenéticamente a dioses ajenos. La imagen es física, una garganta desgarrada por el jadeo desesperado tras los amantes, pero el significado es espiritual. El estado reseco y agotado simboliza tanto la naturaleza extenuante de la idolatría como su incapacidad última para satisfacer.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6774', 'spa', 'tierra sedienta, terreno reseco; tierra seca carente de agua, frecuentemente en contextos de desierto o juicio', 'El término describe tierra sedienta o reseca—terreno que necesita agua desesperadamente. Deuteronomio 8:15 recuerda el viaje por el desierto a través de ''el desierto grande y terrible, con su tierra sedienta''. El Salmo 107:33 describe el juicio de Dios convirtiendo ríos en tierra sedienta. Isaías 35:7 promete restauración: ''la tierra sedienta se convertirá en manantiales''. La palabra evoca aridez y necesidad, ya sea como prueba (Deuteronomio), juicio (Salmo), o la condición que espera redención (Isaías). Las traducciones en diversos idiomas capturan tanto la tierra misma (''terre aride'') como la cualidad abstracta (''sed'', ''thirst'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6775', 'spa', 'atar, unirse, adherirse a; uncirse en lealtad o devoción', 'Este verbo expresa el sentido fundamental de atar o uncir, con una fuerte connotación de adhesión o devoción. Su uso teológicamente más relevante describe a Israel ''uniéndose a'' Baal Peor, es decir, adoptando su culto (Nm 25:3, 5; Sal 106:28). El sentido físico aparece en 2 Samuel 20:8, donde una espada está ''atada'' a la cintura de Joab. El Salmo 50:19 emplea el Hifil para describir el uncir la boca al engaño. Los cognados en árabe, arameo y etiópico convergen en la idea de atar o sujetar, especialmente el enganchar animales al yugo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6776', 'spa', 'Un par o yunta de animales, especialmente bueyes de tiro; por extensión, una yugada — la superficie de tierra que una yunta de bueyes puede arar en un', 'Un par o yunta de animales, especialmente bueyes de tiro; por extensión, una yugada — la superficie de tierra que una yunta de bueyes puede arar en un día. Este sustantivo designa fundamentalmente un par o equipo de animales uncidos juntos para el trabajo. Saúl cortó una yunta de bueyes (צֶמֶד בָּקָר) y envió los pedazos por todo Israel como convocatoria a la guerra (1 Samuel 11:7), y Eliseo estaba arando con doce yuntas de bueyes cuando Elías lo llamó (1 Reyes 19:19). La palabra se extiende naturalmente a una medida de tierra: una yugada, definida como el área que una yunta de bueyes podía arar en un día. Isaías 5:10 profetiza que ''diez yugadas de viña'' (עֲשֶׂרֶת צִמְדֵּי כֶרֶם) producirán solo un bato, una imagen devastadora de fracaso agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6777', 'spa', 'velo (cobertura femenina para la cabeza o el rostro)', 'Velo o cobertura femenina para la cabeza, presente en Cantares e Isaías. En Cantares aparece tres veces (4:1, 3; 6:7) describiendo los ojos o las mejillas de la amada visibles tras su velo, imagen de belleza modesta y cautivadora. Isaías 47:2 ordena a Babilonia personificada «quita tu velo» como parte de su exposición humillante y exilio. El velo representa recato, dignidad femenina y decoro; su remoción significa vergüenza y vulnerabilidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6778', 'spa', 'tortas de pasas, racimos de pasas (uvas secas prensadas en tortas)', 'Uvas secas prensadas o agrupadas, ya sea como tortas de pasas o racimos de pasas. Eran alimento portátil y energético, usado como provisión en viajes o campañas militares. 1 Samuel 25:18 menciona que Abigail llevó tortas de pasas a David junto con otras provisiones. 1 Samuel 30:12 describe cómo dieron pasas a un siervo egipcio moribundo de hambre. 2 Samuel 16:1 incluye tortas de pasas entre los suministros que Siba trajo para la huida de David. 1 Crónicas 12:40 registra que los vecinos trajeron pasas a la fiesta de coronación de David. Era un sustento valioso y fácil de transportar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6779', 'spa', 'Brotar, germinar (de plantas o crecimiento figurado); hacer crecer o producir (Hifil); crecer intensamente (Piel)', 'Brotar, germinar (de plantas o crecimiento figurado); hacer crecer o producir (Hifil); crecer intensamente (Piel)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6780', 'spa', 'Brote, crecimiento, vegetación; usado como título mesiánico ''el Renuevo'' para el gobernante davídico prometido', 'Sustantivo cuyo significado natural — el crecimiento verde que brota de la tierra — se convierte en una de las imágenes mesiánicas más evocadoras del Antiguo Testamento. Génesis 19:25 lo usa simplemente para el ''crecimiento del suelo'' destruido en Sodoma, y Ezequiel 16:7 compara a Jerusalén con el ''crecimiento del campo''. Pero en Jeremías 23:5 y Zacarías 3:8 y 6:12, tsemach se transforma en un título real: ''el Renuevo'', el vástago justo que Dios levantará del linaje de David. El español capta bellamente esta transición — de ''su brote'' a ''el Retoño'' como nombre propio. La tensión entre el humilde crecimiento terrenal y la exaltada promesa mesiánica es el corazón teológico de esta palabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6781a', 'spa', 'Brazalete o pulsera; banda ornamental llevada en la muñeca o el brazo, dada como obsequio, dote o botín.', 'Un brazalete o pulsera, banda ornamental que se lleva en la muñeca o el brazo. El término aparece de manera prominente en la narración del compromiso de Rebeca, donde el siervo de Abraham presenta brazaletes de oro como señal de cortejo (Gn 24:22, 30, 47). Reaparece entre los despojos de guerra dedicados al SEÑOR (Nm 31:50) y en las descripciones alegóricas de Ezequiel, donde Jerusalén es una novia engalanada por Dios con brazaletes (Ez 16:11; 23:42). Las traducciones en distintos idiomas son notablemente uniformes: español ''brazaletes'', francés ''bracelets'', alemán ''Armreife'', lo cual refleja la concreción y universalidad cultural de este referente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6781b', 'spa', 'cubierta, tapa (de un recipiente), tapadera atada o asegurada', 'Este sustantivo designa una cubierta o tapa para un recipiente, mencionado en las regulaciones de pureza de Números 19:15. Todo recipiente abierto que careciera de una tapa firmemente atada dentro de una tienda donde hubiera un cadáver quedaba impuro. La ley exigía que los recipientes estuvieran sellados para impedir la contaminación por contacto con la muerte. La palabra enfatiza el aspecto de sujeción: la tapa debía estar asegurada, no simplemente colocada encima, para brindar protección ritual eficaz contra la influencia contaminante de la muerte.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6784', 'spa', 'secarse, marchitarse, resecarse', 'Este verbo significa secarse o marchitarse, y aparece en la amarga oración de Oseas 9:14 sobre el juicio contra Israel. El profeta pide a Dios que dé a Efraín «pechos resecos» incapaces de amamantar, una imagen devastadora de esterilidad y maternidad frustrada. La expresión paralela «vientre que aborta» refuerza el tema de una generación truncada. El verbo capta el marchitamiento de lo que debería dar vida y sustento, un lenguaje biológico que expresa la extinción nacional.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6785', 'spa', 'Lana — el vellón de oveja como materia prima, producto textil o imagen de blancura. Designa el vellón fibroso de las ovejas tanto en usos prácticos co', 'Lana — el vellón de oveja como materia prima, producto textil o imagen de blancura. Designa el vellón fibroso de las ovejas tanto en usos prácticos como figurados. Aparece con mayor frecuencia emparejado con el lino en contextos legales y económicos: las leyes de contaminación de vestiduras (Lv 13:47-59), la prohibición de mezcla de tejidos (Dt 22:11) y la descripción de Oseas de la lana como don valioso (Os 2:7, 11). Isaías usa la lana blanca como símil de pecado purificado — ''aunque vuestros pecados sean como la grana, serán blancos como la lana'' (Is 1:18) — mientras el salmista compara la nieve con lana esparcida por la tierra (Sal 147:16). Ezequiel prohíbe vestiduras sacerdotales de lana para evitar la transpiración (Ez 44:17). La mujer de Proverbios 31 busca lana junto con lino para la industria de su hogar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6788', 'spa', 'copa de árbol, cima; las ramas frondosas más altas, especialmente de un cedro alto', 'Derivado de la raíz asociada con la lana o el vellón, este sustantivo evoca la copa suave y plumosa de un árbol. Las cinco apariciones se encuentran en la imaginería profética de Ezequiel, donde la copa de un gran cedro simboliza la soberanía real y el orgullo nacional (Ez 17:3, 22; 31:3, 10, 14). Tanto la glosa inglesa ''top'' como la española ''copa'' captan la imagen del dosel elevado, mientras que el vínculo etimológico con la lana evoca la cualidad densa y tupida del follaje en el ápice de un árbol.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6789', 'spa', 'Poner fin a, destruir, aniquilar; en voz pasiva, perecer o ser cortado; en forma intensiva, consumir por completo. Un verbo contundente de destrucción', 'Poner fin a, destruir, aniquilar; en voz pasiva, perecer o ser cortado; en forma intensiva, consumir por completo. Un verbo contundente de destrucción total, usado casi exclusivamente en poesía y lamento. David declara ''destruí a los que me aborrecen'' (2 Sam 22:41), el salmista suplica ''¡destrúyelos!'' (Sal 54:5), y en Lamentaciones los enemigos ''acabaron con mi vida en la fosa'' (Lam 3:53). El cognado árabe significa ''silenciar'', y ese matiz persiste: no se trata de mero daño sino de un final definitivo. El español capta bien el espectro: ''destruir'' para el Hifil, ''desaparecer'' para el Nifal, y ''consumir'' para la fuerza intensiva del Piel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6790', 'spa', 'Zin; región desértica en el sur del Néguev asociada con Cadés-barnea y las peregrinaciones de Israel.', 'Nombre propio que designa el desierto de Zin, una región árida en el sur del Néguev por la que Israel transitó durante el Éxodo. Está estrechamente asociada con Cadés-barnea (Núm 20:1; 27:14) y aparece de manera prominente en las descripciones de los límites de la Tierra Prometida (Núm 34:3-4; Jos 15:1). Esta es también la región donde murió Miriam y donde Moisés golpeó la roca en Meribá. Las transliteraciones varían entre idiomas —Tsin, Tzin, Sin— pero todas se refieren al mismo lugar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6793a', 'spa', 'ganchos, garfios (para pescar o arrastrar)', 'Este sustantivo designa ganchos o garfios, posiblemente anzuelos de pesca, mencionados en Amós 4:2. El profeta declara que los enemigos arrastrarán al pueblo de Samaria «con ganchos», empleando la imaginería de la pesca para describir la deportación. En paralelo con «anzuelos» en el mismo versículo, este término puede distinguir tipos de ganchos o enfatizar la totalidad: todo método de captura de peces aplicado a la captura de personas. Son instrumentos punzantes y con púas para arrastrar cautivos sin posibilidad de escape.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6793b', 'spa', 'frescura, frío', 'Este sustantivo denota frescura o frío, y aparece en el símil de Proverbios 25:13 sobre el mensajero fiel. Se le compara con «el frescor de la nieve en tiempo de siega», un alivio refrescante, vigorizante e inesperado. En el contexto del Medio Oriente, el agua enfriada con nieve durante la calurosa temporada de cosecha era un lujo extraordinario. La comparación resalta cómo un mensajero confiable trae un alivio revitalizante a quienes lo envían, tan bienvenido como el frío en medio del calor agobiante.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6793c', 'spa', 'Escudo grande (צִנָּה), un escudo de cuerpo entero distinguido del מָגֵן más pequeño, usado en la guerra y como figura de protección divina. Designa e', 'Escudo grande (צִנָּה), un escudo de cuerpo entero distinguido del מָגֵן más pequeño, usado en la guerra y como figura de protección divina. Designa el escudo defensivo grande de cuerpo completo utilizado por la infantería pesada, en contraste con el מָגֵן más pequeño portado por tropas ligeras. Los escudos de oro de Salomón (1 R 10:16; 2 Cr 9:15) demuestran su tamaño impresionante, y el escudero de Goliat llevaba uno delante del gigante (1 S 17:7, 41). La frase emparejada ''מָגֵן y צִנָּה'' se convirtió en expresión fija del armamento militar completo (Jer 46:3; Ez 23:24; 38:4; 39:9; Sal 35:2). De modo notable, dos Salmos la aplican a Dios — su favor rodea al justo como צִנָּה (Sal 5:12), y su fidelidad es escudo y adarga (Sal 91:4).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6795', 'spa', 'descender, bajarse, descender; movimiento hacia abajo, especialmente al desmontar de un animal o penetrar en la tierra', 'Este verbo describe descender o bajar. Josué 15:18 y Jueces 1:14 relatan cómo Acsa se bajó de su asno para hablar con su padre Caleb—un descenso deliberado para hacer una petición. Jueces 4:21 lo usa para la estaca de la tienda de Jael penetrando hacia abajo en la cabeza de Sísara, clavada ''en la tierra''. El rango semántico cubre tanto el descenso físico ordinario (bajarse de un animal) como la penetración violenta hacia abajo. El español distingue ''se bajó'' (desmontó) de ''penetró'' (penetró), reconociendo la variación contextual dentro del movimiento básico descendente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6797', 'spa', 'turbante, tocado enrollado; prenda de tela enrollada usada por sacerdotes, realeza o mujeres', 'Un turbante o tocado de tela enrollada que denota dignidad y autoridad. En Zacarías 3:5 el sumo sacerdote Josué recibe un turbante limpio como señal de santidad restaurada, mientras que Job 29:14 lo emplea figuradamente: la justicia era su turbante. Isaías 62:3 lo empareja con la realeza (''turbante de realeza''), e Isaías 3:23 enumera los turbantes de las mujeres entre las prendas de lujo destinadas a ser retiradas. Los términos españoles ''turbante'' y ''diadema'' reflejan conjuntamente el abanico que va desde el tocado cotidiano hasta la insignia regia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6798', 'spa', 'reseco, marchito, endurecido', 'Este participio describe algo reseco o marchito, usado en Génesis 41:23 para las espigas del sueño de Faraón. El sueño presenta siete espigas delgadas y abrasadas por el viento del este, descritas como «marchitas», secas por completo e incapaces de dar grano. El cognado arameo significa «piedra», lo que sugiere un endurecimiento por desecación. Estas espigas marchitas simbolizaban siete años de hambruna que consumirían la abundancia de Egipto: grano tan reseco que resultaba inútil para alimento o siembra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6799', 'spa', 'Zenán, ciudad en la Sefela de Judá', 'Este topónimo identifica una ciudad en la Sefela (tierras bajas) de Judá, mencionada en Josué 15:37. Posiblemente sea la misma localidad que aparece en Miqueas 1:11 como Zaanán (o Tsenán). La Septuaginta la transcribe como Senna o Sennam. Como parte del territorio asignado a Judá, era una de las ciudades situadas en la zona baja entre la llanura costera y la serranía, ubicada estratégicamente en una fértil región agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6800a', 'spa', 'Caminar humildemente, conducirse con humildad', 'Este verbo en infinitivo absoluto Hifil significa caminar humildemente o conducirse con modestia. Miqueas 6:8 lo emplea en el célebre resumen de lo que Dios requiere: «practicar la justicia, amar la misericordia y caminar humildemente con tu Dios». La forma intensiva del infinitivo subraya el carácter continuo de ese andar humilde. La raíz sugiere ser reservado o modesto, lo opuesto al orgullo. No se trata de humildad ocasional, sino de una postura constante de modestia ante Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6800b', 'spa', 'Humilde, modesto (en carácter)', 'Este adjetivo describe a personas humildes o modestas, y aparece en Proverbios 11:2 en contraste con la arrogancia. El versículo afirma que «con los humildes está la sabiduría», mientras que el orgullo trae deshonra. La forma plural designa a quienes se caracterizan por la modestia y la sencillez, no por la presunción. No se trata de debilidad, sino de una justa valoración de uno mismo. La sabiduría gravita hacia las personas humildes y se aparta de los soberbios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6801', 'spa', 'enrollar, envolver firmemente, ceñir (especialmente envolver la cabeza con un turbante)', 'Verbo que significa enrollar, envolver o ceñir algo firmemente, particularmente envolver la cabeza con un turbante. En Levítico 16:4, se instruye al sumo sacerdote a «envolver su cabeza» con el turbante de lino en el Día de la Expiación. Isaías 22:18 emplea formas intensivas para describir cómo Dios «te enrollará apretadamente» como una pelota para lanzarte al exilio. La imagen transmite la idea de envolver algo por completo, ya sea en honor (turbante sacerdotal) o en juicio (atado para el destierro).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6802', 'spa', 'Enrollamiento, envoltura o turbante', 'Este sustantivo parece significar enrollamiento, envoltura o posiblemente un turbante, y aparece en Isaías 22:18. El contexto es el juicio de Dios contra Sebna, con imágenes de envolver y lanzar como una pelota. El significado exacto es debatido: algunos lo interpretan como un turbante o tela envolvente, otros como la acción de enrollar. La raíz verbal significa envolver o enrollar, por lo que este sustantivo probablemente designa el objeto enrollado o la acción misma de enrollar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6803', 'spa', 'Vasija, jarra (para almacenar el maná)', 'Este sustantivo designa una vasija o recipiente, y aparece en Éxodo 16:33, donde Moisés ordena a Aarón: «Toma una vasija y pon en ella un gomer de maná» para conservarlo ante el Señor. Este recipiente debía guardarse para las generaciones futuras como testimonio. El Targum sugiere una canasta, pero el contexto y otras versiones apoyan la traducción «vasija», un recipiente adecuado para la conservación prolongada del pan preservado. El tipo específico de recipiente importaba para esta función conmemorativa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6804', 'spa', 'tubos o conductos (para llevar aceite a las lámparas)', 'Este sustantivo masculino plural en estado constructo designa tubos o conductos, y aparece en Zacarías 4:12 dentro de la visión del candelabro de oro. El profeta contempla ''dos tubos de oro'' que vierten aceite dorado desde los olivos hacia la lámpara. Estos conductos transportaban el aceite desde la fuente hasta la llama, asegurando su provisión continua. La imagen subraya un suministro inagotable: los tubos garantizan un flujo constante desde la fuente divina hacia la función de iluminar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6805', 'spa', 'Dar pasos, marchar o avanzar con zancadas firmes; en Hifil, hacer que alguien sea conducido o llevado a marchar.', 'Verbo que expresa un movimiento deliberado y solemne: la zancada medida de un guerrero, de una deidad o de una procesión sagrada. En el Cántico de Débora (Jue 5:4) y en el Salmo 68:7, Dios mismo «avanza» desde Seír y a través del desierto, y las traducciones en múltiples lenguas convergen notablemente: español «cuando marchaste», francés «dans marcher», todas captando esa cadencia majestuosa. En Job 18:14, el Hifil desplaza la acción hacia afuera: la muerte «lo hace marchar» ante el rey de los espantos, un causativo estremecedor que el hindi traduce como «lo llevará» (उसे ले जाएगी), subrayando la compulsión frente al movimiento voluntario.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6806', 'spa', 'Un paso, zancada o pisada; literalmente una huella del pie, figuradamente el curso y la dirección de la vida de una persona. Se refiere a un solo paso', 'Un paso, zancada o pisada; literalmente una huella del pie, figuradamente el curso y la dirección de la vida de una persona. Se refiere a un solo paso o zancada del pie, abarcando usos tanto literales como profundamente figurados. David celebra que Dios ''ensancha mis pasos debajo de mí'', dándole una pisada firme y segura (2 Sam 22:37 = Sal 18:36). Proverbios observa que ''los pasos del hombre los dirige el SEÑOR'' (Prov 16:9), y Jeremías confiesa que ''los pasos del hombre no están en su propio poder'' (Jer 10:23). Job invoca la palabra repetidamente en contextos de vigilancia divina: ''¿Acaso no ve Él mis pasos y los cuenta todos?'' (Job 31:4, 37). El plural en Proverbios 30:29 describe criaturas ''majestuosas en su andar''. Lamentaciones 4:18 lo usa para pasos acechados por perseguidores, cerrando el cerco sobre una ciudad sitiada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6807b', 'spa', 'brazaletes, bandas ornamentales para la parte superior del brazo', 'Este sustantivo designa bandas ornamentales o brazaletes que se llevaban en la parte superior del brazo, mencionados entre las joyas femeninas en Isaías 3:20. Aunque algunos traducen ''cadenillas para los tobillos'', la interpretación más acertada es la de brazaletes que ceñían el brazo. Eran artículos de lujo, parte del elaborado adorno que el profeta condena. Algunos eruditos proponen leer esta misma palabra en 2 Reyes 11:12 como brazaletes reales colocados a Joás en su coronación, marcando así estatus y riqueza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6808', 'spa', 'Encorvarse, inclinarse; volcar un recipiente; avanzar doblado por el esfuerzo', 'Un verbo que describe el acto físico de encorvarse o doblarse bajo tensión. En Isaías 51:14 retrata a un cautivo agobiado bajo cargas, mientras que Isaías 63:1 presenta a alguien que avanza inclinado con fuerza abundante. Jeremías 2:20 emplea la postura en sentido moral, describiendo a quien se tiende en la prostitución. En Jeremías 48:12 la imagen cambia al acto de volcar y vaciar vasijas, metáfora vívida de la devastación venidera sobre Moab. El español capta bien este abanico: ''encorvado'' (agachado), ''marchando'' (avanzando) y ''trasegar'' (trasvasar).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6809', 'spa', 'velo, manto, chal; una cubierta para la cabeza o prenda usada por mujeres para modestia u ocultamiento de identidad', 'Este sustantivo se refiere a un velo o cubierta para la cabeza usado por mujeres. Génesis 24:65 describe a Rebeca cubriéndose con un velo cuando ve a Isaac acercándose—un acto de modestia antes de conocer a su futuro esposo. Génesis 38:14, 19 muestra a Tamar usando un velo para disfrazarse como prostituta y luego quitárselo después. La prenda sirve tanto para la modestia (Rebeca) como para el disfraz (Tamar), funcionando como un marcador de identidad y estatus social. Las traducciones en diversos idiomas reconocen uniformemente esto como un velo o chal (francés ''voile'', alemán ''Schleier'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6810', 'spa', 'Pequeño, joven, insignificante — el hermano menor, el último en rango, o alguien de poca edad o estatus', 'Pequeño, joven, insignificante — el hermano menor, el último en rango, o alguien de poca edad o estatus');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6811', 'spa', 'Zair, una localidad cercana a Edom', 'Este topónimo aparece en 2 Reyes 8:21, donde Joram cruza hacia Zair para combatir a los edomitas. La ubicación exacta es incierta, probablemente en la frontera con Edom o cerca de ella. La Septuaginta lo traduce como Seir o Sior. El contexto narrativo es la revuelta exitosa de Edom contra Judá: Joram marchó a Zair, fue rodeado de noche, logró abrirse paso, pero finalmente no pudo sofocar la rebelión. El sitio exacto permanece sin identificar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6812', 'spa', 'juventud, condición de ser más joven', 'Este sustantivo significa juventud o la condición de ser menor en edad. Aparece en Génesis 43:33, donde los hermanos de José son sentados ''conforme a la primogenitura y conforme a la juventud'', es decir, del mayor al menor. La construcción con sufijo indica ''según su juventud'' u ''en orden de menor edad''. Esta disposición sistemática por edad asombró a los hermanos, ya que aquel oficial egipcio —en realidad José— no tenía forma aparente de conocer su orden de nacimiento. El sustantivo capta la posición relativa de juventud dentro de una jerarquía de edad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6813', 'spa', 'vagar, trasladarse, partir (referido al movimiento de tiendas)', 'Este verbo aparece una sola vez, en Isaías, describiendo una tienda que no será movida ni reubicada. La raíz comparte cognados en otras lenguas semíticas relacionados tanto con viajar como con cargar animales de carga, lo que evoca el desplazamiento nómada. En Isaías 33:20, el profeta presenta a Sion como una morada segura cuyas estacas nunca serán arrancadas, empleando este verbo para subrayar la permanencia al negar la idea de errar o partir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6814', 'spa', 'Zoán — antigua ciudad egipcia (Tanis) en el delta del Nilo, sede de la corte faraónica.', 'Nombre hebreo de la antigua ciudad egipcia de Tanis (en griego), situada en el noreste del delta del Nilo. Las Escrituras la recuerdan como el lugar donde Dios obró prodigios ante Faraón (Sal 78:12, 43) y como sede del poder egipcio cuyos consejeros Isaías ridiculiza como necios (Isa 19:11, 13; 30:4). Números 13:22 señala que Hebrón fue edificada siete años antes que Zoán, usándola como referencia cronológica de gran antigüedad. El sitio moderno es San el-Hagar en Egipto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6815', 'spa', 'Zaananim; nombre de lugar en la frontera de Neftalí cerca de Cedes, ubicación de la tienda de Heber el ceneo', 'Zaananim es un nombre de lugar que aparece en descripciones de fronteras y narrativas de batalla. Josué 19:33 lo incluye en la frontera territorial de Neftalí. Jueces 4:11 ubica el campamento de Heber el ceneo ''en Zaananim, cerca de Cedes'', preparando el escenario para el encuentro de Jael con Sísara. El nombre aparece con la preposición beth, lo que lleva a cierto debate sobre si la beth es parte del nombre o un marcador locativo separado. La ubicación exacta del sitio permanece incierta, aunque su asociación con Cedes y la narrativa de Débora-Barac lo sitúa en el norte de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6816', 'spa', 'objetos esculpidos, figuras talladas, obra escultórica (especialmente de querubines)', 'Este sustantivo plural aparece únicamente en 2 Crónicas para describir los querubines del templo de Salomón. El término designa figuras talladas o esculpidas, literalmente ''cosas formadas'' u ''obra de imagen''. Las traducciones captan su carácter escultórico, mientras algunas versiones simplemente transliteran el hebreo, quizá por incertidumbre sobre el tipo exacto de trabajo artístico. No eran meros elementos decorativos, sino imágenes sagradas que representaban seres angélicos en el Lugar Santísimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6817', 'spa', 'El grito urgente de quienes se hallan en necesidad desesperada: esclavos en Egipto, israelitas oprimidos bajo dominio extranjero, una voz solitaria qu', 'El grito urgente de quienes se hallan en necesidad desesperada: esclavos en Egipto, israelitas oprimidos bajo dominio extranjero, una voz solitaria que clama al rey por justicia. Casi cada aparición carga el peso de una angustia genuina dirigida hacia alguien que puede ayudar: ''y los hijos de Israel clamaron a Yahvé'' es prácticamente un estribillo en Jueces. En su forma Nifal, menos frecuente, el significado pasa de clamar a ser convocado — tropas reunidas para la batalla (Jue 7:23-24), una nación congregada para la guerra. Ambos sentidos comparten el elemento de un acto vocal público y fuerte, pero difieren en dirección: uno suplica hacia arriba, el otro convoca hacia afuera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6818', 'spa', 'Clamor o grito de angustia, aflicción o protesta, que frecuentemente llega a Dios como apelación por justicia. Un grito fuerte y angustiado — ya sea d', 'Clamor o grito de angustia, aflicción o protesta, que frecuentemente llega a Dios como apelación por justicia. Un grito fuerte y angustiado — ya sea de dolor individual u opresión colectiva — que se eleva como súplica implícita o explícita pidiendo intervención divina. El clamor de Sodoma (Gn 18:21; 19:13) movió a Dios a investigar; el clamor de Israel en Egipto (Éx 3:7, 9) lo movió a liberar. Nehemías 5:1 registra tal clamor contra la injusticia económica dentro de la propia comunidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6819', 'spa', 'ser insignificante, volverse pequeño, ser humillado; disminuir en estatus, honor o número', 'Este verbo significa volverse insignificante, pequeño o disminuido—lo opuesto a ser honrado o numeroso. Job 14:21 habla de hijos que son humillados sin que el padre lo sepa. Jeremías 30:19 promete que el pueblo restaurado de Dios ''no será menospreciado''—crecerán y serán honrados. Zacarías 13:7 menciona ''los pequeños'' entre las ovejas dispersas, aquellos de menor estatus o fuerza. El campo semántico abarca tanto la disminución numérica como el menosprecio social. El español distingue ''menospreciados'' (despreciados/humillados) de ''pequeños'' (los de menor tamaño), capturando ambos matices.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6820', 'spa', 'Zoar; pequeña ciudad al extremo sureste del mar Muerto adonde Lot huyó de la destrucción de Sodoma.', 'El nombre Zoar (que significa ''pequeña, insignificante'') pertenece a una de las cinco ciudades de la llanura, originalmente llamada Bela (Gén 14:2, 8). Se convirtió en el refugio de Lot cuando suplicó que era ''una pequeñita'' y fue librada del juicio de fuego que consumió a Sodoma y Gomorra (Gén 19:22-23). Referencias proféticas posteriores en Isaías 15:5 y Jeremías 48:34 mencionan a Zoar en oráculos contra Moab, confirmando su ubicación cerca de la costa sureste del mar Muerto. Moisés la divisó desde el monte Nebo (Deut 34:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6821', 'spa', 'contraerse, encogerse, adherirse (de la piel pegada a los huesos)', 'Este verbo aparece únicamente en la estremecedora descripción de Lamentaciones sobre las víctimas de la hambruna en Jerusalén. La raíz transmite la contracción física de la piel que se tensa y reseca sobre los huesos, una imagen visceral de los efectos de la inanición. En lenguas emparentadas, la raíz se asocia con atar o encadenar, lo que sugiere el carácter constrictivo de este deterioro corporal. El español ''pegado'' capta bien cómo la piel se adhiere de manera antinatural al esqueleto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6822', 'spa', 'Otear, espiar, vigilar; como sustantivo: atalaya, centinela — de צָפָה ''mirar desde lo alto, observar''', 'Otear, espiar, vigilar; como sustantivo: atalaya, centinela — de צָפָה ''mirar desde lo alto, observar''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6823', 'spa', 'Revestir o chapear una superficie con metal (oro, bronce, plata), especialmente en la construcción del tabernáculo y el templo', 'Revestir o chapear una superficie con metal (oro, bronce, plata), especialmente en la construcción del tabernáculo y el templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6824', 'spa', 'flujo, derramamiento (de sangre)', 'Este raro sustantivo femenino aparece únicamente en el oráculo de Ezequiel contra el faraón, refiriéndose a sangre que fluye. El contexto describe la sangre que mana del ejército caído de Egipto, en volumen suficiente para empapar la tierra. El término enfatiza la naturaleza líquida y fluyente de la sangre, no como sustancia estática sino en movimiento. La imagen evoca oleadas de sangre derramándose por el campo de batalla.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6825', 'spa', 'Tsefo/Tsefi; nombre personal de un jefe edomita, nieto de Esaú por medio de Elifaz', 'Tsefo (también escrito Tsefi) fue un líder edomita, hijo de Elifaz y nieto de Esaú. Génesis 36:11, 15 lo enumeran entre los jefes de Edom, mientras que 1 Crónicas 1:36 usa la variante ortográfica Tsefi. El nombre aparece en registros genealógicos que trazan los descendientes de Esaú que llegaron a ser líderes tribales en Edom. La variación ortográfica entre Génesis y Crónicas es típica de textos genealógicos paralelos. La evidencia interlingüística refleja ambas formas (Zepho/Zefo y Zephi/Tsefi), con referencias entre corchetes marcando la variante ortográfica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6826', 'spa', 'Chapado metálico, revestimiento; cobertura delgada de oro o plata aplicada a objetos', 'Sustantivo que designa la cobertura metálica delgada aplicada a objetos sagrados o idolátricos. En Éxodo 38:17, 19 se refiere al chapado de oro o plata sobre los capiteles de las columnas del tabernáculo. Números 16:38-39 describe incensarios de bronce martillados hasta convertirlos en planchas de revestimiento para el altar como memorial. Isaías 30:22 lo emplea despectivamente para la cubierta de plata sobre imágenes talladas destinadas a ser desechadas. El término español ''revestimiento'' capta bien la idea de una funda metálica decorativa colocada sobre una estructura base.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6827', 'spa', 'Sefón (hijo de Gad, progenitor del clan sefonita)', 'Este nombre propio designa a un hijo de Gad y fundador de un clan. El nombre aparece en dos formas en las Escrituras: Sefón en Números 26:15 y Zifión en Génesis 46:16, refiriéndose a la misma persona. Su etimología podría estar relacionada con ''mirar'' u ''observar'', aunque esto sigue siendo incierto. El clan que descendió de él se conoció como los sefonitas, uno de los grupos familiares dentro de la tribu de Gad que entraron en Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6828', 'spa', 'Norte, dirección septentrional; el norte como origen de invasión y juicio; Safón, la montaña sagrada', 'Derivado de una raíz que significa ''ocultar'' u ''oscurecer'', צָפוֹן designa el punto cardinal norte a lo largo de la Biblia hebrea, con especial frecuencia en Ezequiel (46 veces), Josué (25) y Jeremías (25). Su función direccional —delimitar fronteras, orientar el mobiliario del tabernáculo y asignar territorios tribales— explica la mayoría de sus apariciones. Sin embargo, en la literatura profética el norte adquiere un carácter ominoso: el mal ''se desata desde el norte'' (Jer 1:14; 4:6; 6:1), y vastos ejércitos descienden del horizonte septentrional como instrumentos de la ira divina. Tras esta geografía late la mitología del antiguo Oriente Próximo, donde el monte Safón (ugarítico Sapanu) era la montaña de los dioses, tradición que el salmista reclama deliberadamente al llamar a Sion ''las alturas de Safón'' (Sal 48:3).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6829', 'spa', 'Safón (ciudad al este del Jordán en el territorio de Gad)', 'Este topónimo identifica una ciudad en el territorio tribal de Gad, al este del río Jordán. Fuentes antiguas la sitúan cerca del río Jaboc, posiblemente en la actual Amateh. El nombre podría compartir la misma raíz que la palabra común para ''norte'', aunque aquí funciona como nombre propio de un asentamiento específico. Josué 13:27 y Jueces 12:1 mencionan esta localidad transjordana, importante en la organización territorial temprana de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6830', 'spa', 'el norteño, invasor del norte (posiblemente langostas o ejército extranjero)', 'Este adjetivo, usado de forma sustantivada con el artículo, designa «el del norte»: un invasor o amenaza procedente del septentrión. Joel 2:20 aplica este término a lo que la mayoría de los intérpretes entienden como una plaga de langostas, aunque la imaginería se entrelaza con la de una invasión militar. El norte era la dirección tradicional desde la que los ejércitos mesopotámicos se acercaban a Israel, lo que convierte a «el norteño» en un término cargado de connotaciones de amenaza extranjera y juicio divino. La plaga de langostas funciona así como desastre agrícola literal y símbolo profético a la vez.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6831', 'spa', 'el sefonita (descendiente de Sefón, clan de la tribu de Gad)', 'Este adjetivo gentilicio identifica a los miembros del clan sefonita dentro de la tribu de Gad. Usado colectivamente con el artículo definido, designa a todos los descendientes de Sefón (o Zifión) registrados en el censo del desierto. Tales designaciones de clan eran esenciales para la herencia de tierras, la organización militar y el mantenimiento de los registros genealógicos. Números 26:15 emplea este término para clasificar a este grupo familiar dentro de la estructura tribal más amplia de Gad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6833', 'spa', 'Ave, pájaro, gorrión — un ave pequeña o cualquier ave en sentido genérico; usada en la purificación ritual y como figura de libertad', 'Ave, pájaro, gorrión — un ave pequeña o cualquier ave en sentido genérico; usada en la purificación ritual y como figura de libertad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6834', 'spa', 'Zipor — nombre propio, padre de Balac rey de Moab; significa «pájaro» o «gorrión».', 'Nombre propio masculino que significa «pájaro» (posiblemente «gorrión»), llevado por el padre de Balac, rey de Moab, quien contrató a Balaam para maldecir a Israel. El nombre aparece siete veces, siempre identificando el linaje de Balac (Núm 22:2, 4, 10, 16; 23:18; Jos 24:9; Jue 11:25). Este nombre zoológico sigue un patrón semítico común de usar nombres de animales para personas, paralelo al nombre palmireno Tsipra. Todas las traducciones simplemente lo transliteran: tanto el inglés como el español, el francés y el alemán lo vierten como «Zipor».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6835', 'spa', 'Jarra o frasco pequeño para transportar agua o aceite, usado en las narrativas de Saúl-David y de Elías.', 'Sustantivo femenino que designa una jarra o frasco pequeño, de cuerpo aplanado, utilizado para contener agua o aceite. En las narrativas de David y Saúl, es la vasija de agua que David arrebató de junto a la cabecera del rey dormido como prueba de su misericordia (1 Sam 26:11, 12, 16). En el ciclo de Elías, es la vasija de aceite de la viuda de Sarepta que milagrosamente nunca se agota (1 Re 17:12, 14, 16) y el cántaro de agua dejado por el ángel junto a la cabecera de Elías (1 Re 19:6). El español «vasija» y el inglés «jug/flask» confirman un único referente concreto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6836', 'spa', 'atalaya, puesto de vigilancia; acto de vigilar', 'Este sustantivo aparece únicamente en Lamentaciones, describiendo la vigilia infructuosa de Judá en busca de ayuda durante el asedio de Jerusalén. El término probablemente deriva de raíces que significan «vigilar» u «otear», y sugiere tanto una atalaya física como el acto mismo de vigilar. La expresión «en nuestra vigilia vigilábamos» combina este sustantivo con su forma verbal, creando énfasis por repetición: vigilaban y vigilaban, pero ningún rescatador llegó. El aliado militar esperado jamás se materializó.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6837', 'spa', 'Zifión (hijo de Gad, forma alternativa de Sefón)', 'Este nombre propio designa al mismo individuo llamado Sefón en Números 26:15. Génesis 46:16 emplea esta grafía al enumerar a los descendientes de Jacob que bajaron a Egipto. Tales variantes ortográficas para una misma persona son frecuentes en las genealogías hebreas y a menudo reflejan diferencias dialectales o tradiciones escribales. Este individuo fundó uno de los clanes dentro de la tribu de Gad, designado posteriormente como los sefonitas en el censo del desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6838', 'spa', 'torta plana, oblea (pan delgado)', 'Este sustantivo designa un tipo de pan fino y plano, similar a una oblea o galleta. Éxodo 16:31 lo emplea para describir la apariencia del maná, comparando la provisión divina con un alimento horneado conocido. El término sugiere algo delgado y delicado, más semejante a una oblea o galleta que a un pan grueso. Esta comparación ayudó a Israel a conceptualizar el maná desconocido mediante referencia a productos horneados familiares, resaltando tanto su carácter nutritivo como su textura única y delicada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6839', 'spa', 'Zofim (lugar elevado donde Balaam bendijo a Israel)', 'Este topónimo significa «vigías» o «atalayas» y designa el lugar al que Balac llevó a Balaam para divisar el campamento de Israel. Números 23:14 lo identifica como un campo en la cumbre del Pisga, un punto elevado con vista panorámica sobre el campamento israelita. Desde este «campo de los vigías», Balaam pronunció su segundo oráculo bendiciendo a Israel en lugar de maldecirlo, frustrando los planes de Balac. El nombre describe con exactitud su función como puesto de observación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6840', 'spa', 'tesoro, riqueza acumulada o guardada', 'Este sustantivo aparece únicamente en el Salmo 17:14, con una variante textual entre el Ketiv y el Qeré. Designa un tesoro o riqueza almacenada, bienes de valor que han sido atesorados u ocultos. El contexto salmístico habla de aquellos cuya porción está en esta vida, cuyo vientre Dios llena con su tesoro. El término subraya la idea de acumulación y reserva: posesiones preciadas apartadas y guardadas. La variante textual sugiere cierta incertidumbre escribal respecto a la forma original.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6841', 'spa', 'machos cabríos, chivos', 'Este sustantivo plural en arameo aparece en el relato de Esdras sobre la dedicación del segundo templo, dentro de la lista de animales ofrecidos en sacrificio. El término designa específicamente machos cabríos, distinguiéndolos de las cabras hembras y de otros animales. Esdras 6:17 registra que durante las ceremonias de dedicación se ofrecieron machos cabríos como sacrificio por el pecado en representación de todo Israel. El vocabulario arameo en Esdras refleja el carácter bilingüe de la comunidad postexílica y el contexto imperial en que se llevó a cabo la reconstrucción del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6842', 'spa', 'Macho cabrío; empleado en ofrendas sacrificiales y como símbolo de poder en las visiones de Daniel.', 'Un macho cabrío, presente tanto en contextos rituales como apocalípticos. En la visión de Daniel, el tsaphir es el prominente macho cabrío que embiste desde el occidente sin tocar el suelo, simbolizando a Alejandro Magno y el imperio griego (Dn 8:5, 8, 21). En el ámbito cultual, el término designa machos cabríos traídos para ofrendas por el pecado y la rededicación del templo (2 Cr 29:21; Esd 8:35). La expresión española ''macho cabrío'' y la francesa ''bouc'' captan con precisión la especificidad masculina de este término, distinguiéndolo de las palabras más genéricas para cabra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6843', 'spa', 'diadema, chaplet, trenza; una corona tejida o trenzada, posiblemente también ''destino'' en contextos proféticos', 'Este sustantivo probablemente se refiere a un chaplet o corona tejida, aunque su significado es debatido especialmente en Ezequiel. Isaías 28:5 habla del Señor convirtiéndose en ''hermosa diadema'' para el remanente fiel, usando imágenes de honor real. Ezequiel 7:7, 10 presentan dificultades textuales—traducciones antiguas leen ''mañana'', mientras la mayoría de los eruditos modernos proponen ''destino'' o ''juicio'' basándose en cognados arameos, aunque ''diadema'' sigue siendo posible. La palabra puede derivar de una raíz que significa ''trenzar'' o ''rodear'', sugiriendo algo tejido o que viene alrededor. La evidencia interlingüística refleja esta incertidumbre con corchetes e interpretaciones competidoras.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6844', 'spa', 'alfombra, tapete (tendido para reclinarse); posiblemente atalaya', 'Este sustantivo presenta desafíos interpretativos, ya que aparece solo en Isaías 21:5, en una escena vívida de banquete. La mayoría de los eruditos modernos lo entienden como una alfombra o tapete tendido para comer, parte de la descripción que hace Isaías de los líderes babilónicos festejando despreocupadamente antes de su destrucción repentina. El verbo «tender» que lo acompaña respalda esta lectura: tendían la alfombra para reclinarse a la mesa. Una interpretación más antigua lo relacionaba con «atalaya», conectándolo con raíces vinculadas a la vigilancia, pero el contexto de banquete favorece la lectura de alfombra o tapete.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6845', 'spa', 'Esconder, ocultar, atesorar; guardar en secreto o acechar en emboscada; riquezas ocultas o reservas', 'Esconder, ocultar, atesorar; guardar en secreto o acechar en emboscada; riquezas ocultas o reservas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6846', 'spa', 'Sofonías; nombre propio que significa ''YHWH ha escondido/atesorado'', portado por varias figuras del AT incluido el profeta.', 'El nombre Tsephanyah (o Tsephanyahu) significa ''YHWH ha escondido'' o ''YHWH ha atesorado'', combinando tsaphan (''esconder, guardar'') con el nombre divino. Su portador más célebre es el profeta Sofonías, quien profetizó durante el reinado de Josías (Sof 1:1). Un sacerdote llamado Sofonías hijo de Maasías aparece repetidamente en la narrativa de Jeremías: enviado como emisario a Jeremías (Jer 21:1; 37:3), destinatario de la carta de Semaías (Jer 29:25, 29), y ejecutado en Riblá (Jer 52:24; 2 Rey 25:18). Otras dos figuras llevan este nombre en 1 Crónicas 6:36 y Zacarías 6:10, 14.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6847', 'spa', 'Zafnat-Panea (nombre egipcio de trono otorgado a José)', 'Este nombre compuesto representa el nombre de trono egipcio que el faraón le dio a José al elevarlo al cargo de segundo al mando. Génesis 41:45 registra este cambio de nombre como parte de la investidura oficial de José. Los egiptólogos han identificado su significado aproximado como «Dios habla y él vive» o «el que sustenta la vida». Tales nombres egipcios para funcionarios reales eran práctica habitual y marcaban la plena integración de José en la corte egipcia, aunque la narrativa bíblica preserva su identidad hebrea. Las traducciones griegas tuvieron dificultades con la fonología egipcia, produciendo diversas aproximaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6848a', 'spa', 'víbora, serpiente venenosa', 'Este sustantivo designa una serpiente venenosa, posiblemente derivado de una raíz que sugiere un sonido sibilante. En Isaías 14:29 aparece dentro de un oráculo que advierte a Filistea que no se regocije por la caída de su opresor, pues de la raíz de esa serpiente brotará algo aún más mortífero: una víbora. La imagen progresa de una amenaza menor a una mayor, empleando terminología ofídica para representar peligros políticos. El término subraya la naturaleza venenosa y letal de la criatura, distinguiéndola de cualquier serpiente común.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6848b', 'spa', 'víbora, serpiente venenosa (posiblemente la víbora daboia u otra serpiente ponzoñosa)', 'Serpiente venenosa, probablemente una especie de víbora, aunque su identificación exacta es debatida ya que las víboras normalmente no ponen huevos (sin embargo Isaías 59:5 menciona «huevos de víbora»). Isaías 11:8 la empareja con la cobra, prometiendo que un niño jugará sin peligro junto a la cueva de la víbora en la era mesiánica. Isaías 59:5 usa «huevos de víbora» como metáfora de las maquinaciones perversas que eclosionan en maldad. Jeremías 8:17 advierte que Dios enviará serpientes venenosas que no podrán ser encantadas, y Proverbios 23:32 compara los efectos del vino con la mordedura de una víbora.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6849', 'spa', 'retoños, descendientes (como brotes de una planta)', 'Este sustantivo plural aparece únicamente en Isaías 22:24, en paralelo con «descendencia» para describir a los descendientes de una familia. La imagen botánica presenta a los miembros de un linaje como retoños o brotes que crecen de una planta. El contexto habla de Eliaquim como una estaca de la que colgará todo el peso de la casa de su padre, tanto la prole como los retoños. La pareja de términos enfatiza la totalidad, abarcando todas las generaciones y ramas familiares. Esta metáfora orgánica para las relaciones genealógicas resultaba natural en una sociedad agrícola.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6850', 'spa', 'gorjear, piar, susurrar (onomatopeya de sonidos agudos de aves o espíritus)', 'Verbo onomatopéyico que describe el gorjeo, el piar o el susurro: sonidos agudos y tenues como los de las aves o los murmullos inquietantes de los espíritus. Isaías 8:19 advierte contra los médiums y adivinos «que susurran y murmuran». Isaías 10:14 lo usa para describir a pueblos conquistados tan aterrados que ni siquiera emiten un piar. Isaías 38:14 presenta a Ezequías «gorjeando como una golondrina» en su angustia, e Isaías 29:4 retrata a Jerusalén derrotada hablando desde el polvo «como un fantasma» con voz chirriante. La palabra capta emisiones débiles, agudas y a menudo sobrenaturales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6851', 'spa', 'sauce (árbol, posiblemente por el sonido de su follaje al mecerse)', 'Este sustantivo designa un tipo de sauce, cuyo nombre posiblemente derive de un sonido onomatopéyico que evoca el susurro de sus hojas. En Ezequiel 17:5 aparece dentro de una visión alegórica donde una gran águila toma una semilla y la planta «junto a aguas abundantes, poniéndola como un sauce». El símil sugiere un árbol que prospera cerca del agua, algo propio de los sauces que crecen a la orilla de ríos y arroyos. Este posible origen sonoro encaja con la característica del sauce de balancearse y susurrar con el viento a lo largo de las riberas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6852', 'spa', 'partir temprano, marcharse (posiblemente al amanecer)', 'Este verbo aparece únicamente en Jueces 7:3, dentro de las instrucciones de Dios a Gedeón para reducir su ejército. Su interpretación exacta sigue siendo debatida: el texto dice «que vuelva y se marche» del monte Galaad. Algunos lo relacionan con vocablos arameos que significan «mañana», sugiriendo «partir al alba». Otros proponen enmiendas textuales. El sentido básico implica partida o retirada, específicamente permitir que los soldados temerosos abandonaran el campamento antes de la batalla contra Madián. Sea cual sea la etimología precisa, el significado funcional —permiso para marcharse— resulta claro por el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6853', 'spa', 'aves (arameo, colectivo o plural)', 'Palabra aramea para designar a las aves, que aparece exclusivamente en Daniel 4 dentro del sueño de Nabucodonosor y su interpretación. El gran árbol del sueño cobijaba a «las aves del cielo» entre sus ramas, representando el vasto alcance del imperio de Nabucodonosor. Tras la humillación del rey, se ordena a las aves huir del árbol. Más tarde, al ser restaurado el rey, las aves vuelven a hallar refugio. Las aves simbolizan los pueblos y reinos lejanos bajo la protección y el dominio babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6854', 'spa', 'Rana; el anfibio de la plaga egipcia, usado colectivamente y en plural para designar la multitud enviada sobre Egipto. Se refiere exclusivamente a las', 'Rana; el anfibio de la plaga egipcia, usado colectivamente y en plural para designar la multitud enviada sobre Egipto. Se refiere exclusivamente a las ranas en el contexto de la segunda plaga de Egipto y su remembranza litúrgica. El hebreo צְפַרְדֵּעַ aparece tanto como singular colectivo (''la rana subió'', Éx 8:2) como en forma plural (''ranas'', Éx 7:27–8:9). Las traducciones en distintos idiomas son notablemente uniformes — ranas en español, grenouilles en francés, Frösche en alemán — porque el referente es sumamente concreto. Salmos 78:45 y 105:30 recuerdan la plaga en el culto, convirtiendo a esta humilde criatura en un elemento permanente de la memoria de salvación de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6855', 'spa', 'Séfora; nombre personal de la esposa madianita de Moisés, hija de Jetro/Reuel', 'Séfora fue la esposa de Moisés, hija del sacerdote madianita Jetro (también llamado Reuel). Éxodo 2:21 registra su matrimonio cuando Moisés huyó a Madián. En Éxodo 4:25, ella circuncida a su hijo durante el misterioso encuentro donde el Señor procuró matar a Moisés. Éxodo 18:2 menciona que Moisés la había despedido, pero Jetro la trae de regreso a Moisés en el desierto. El nombre significa ''pájaro'' en hebreo. Sus breves pero significativas apariciones destacan momentos de crisis y pacto—circuncisión, separación y reunión.');